#!/usr/bin/env python3
"""Capture a tmux pane with escape codes and print per-cell attribute runs.
Usage: tmuxdump.py <target> [--raw]
"""
import subprocess, sys, re

def parse(line):
    # returns list of (char, state) where state is a tuple (fg,bg,attrs)
    fg = 'd'; bg = 'd'; attrs = set()
    cells = []
    i = 0
    while i < len(line):
        c = line[i]
        if c == '\x1b' and i+1 < len(line) and line[i+1] == '[':
            j = i+2
            while j < len(line) and not ('@' <= line[j] <= '~'):
                j += 1
            params = line[i+2:j]
            final = line[j] if j < len(line) else ''
            i = j+1
            if final != 'm':
                continue
            nums = [int(x) if x else 0 for x in params.split(';')] if params else [0]
            k = 0
            while k < len(nums):
                n = nums[k]
                if n == 0:
                    fg = 'd'; bg = 'd'; attrs = set()
                elif n == 1: attrs.add('b')
                elif n == 2: attrs.add('dim')
                elif n == 3: attrs.add('i')
                elif n == 4: attrs.add('u')
                elif n == 5: attrs.add('blink')
                elif n == 7: attrs.add('r')
                elif n == 9: attrs.add('s')
                elif n == 22: attrs.discard('b'); attrs.discard('dim')
                elif n == 23: attrs.discard('i')
                elif n == 24: attrs.discard('u')
                elif n == 25: attrs.discard('blink')
                elif n == 27: attrs.discard('r')
                elif n == 29: attrs.discard('s')
                elif 30 <= n <= 37: fg = str(n-30)
                elif n == 38:
                    if k+1 < len(nums) and nums[k+1] == 5:
                        fg = str(nums[k+2]); k += 2
                    elif k+1 < len(nums) and nums[k+1] == 2:
                        fg = 'rgb(%d,%d,%d)' % tuple(nums[k+2:k+5]); k += 4
                elif n == 39: fg = 'd'
                elif 40 <= n <= 47: bg = str(n-40)
                elif n == 48:
                    if k+1 < len(nums) and nums[k+1] == 5:
                        bg = str(nums[k+2]); k += 2
                    elif k+1 < len(nums) and nums[k+1] == 2:
                        bg = 'rgb(%d,%d,%d)' % tuple(nums[k+2:k+5]); k += 4
                elif n == 49: bg = 'd'
                elif 90 <= n <= 97: fg = str(n-90+8)
                elif 100 <= n <= 107: bg = str(n-100+8)
                k += 1
        else:
            cells.append((c, (fg, bg, ''.join(sorted(attrs)))))
            i += 1
    return cells

def fmt_state(st):
    fg, bg, attrs = st
    parts = []
    if fg != 'd': parts.append('fg=' + fg)
    if bg != 'd': parts.append('bg=' + bg)
    if attrs: parts.append(attrs)
    return ','.join(parts) if parts else 'plain'

def main():
    target = sys.argv[1]
    out = subprocess.run(['tmux', 'capture-pane', '-t', target, '-p', '-e'], capture_output=True, text=True).stdout
    for ln, line in enumerate(out.split('\n')):
        cells = parse(line)
        if not cells:
            print('%2d:' % ln); continue
        runs = []
        cur = None; buf = ''
        for ch, st in cells:
            if st != cur:
                if cur is not None: runs.append((buf, cur))
                cur = st; buf = ch
            else:
                buf += ch
        runs.append((buf, cur))
        s = ''.join('[%s]%s' % (fmt_state(st), txt) if fmt_state(st) != 'plain' else txt for txt, st in runs)
        print('%2d:%s' % (ln, s))

main()
EOF
