import itertools, os, sys

def build_entries(root):
    """Return DFS list of (depth, name, own_size, is_dir) in readdir order, root at depth 0."""
    out = []
    def walk(path, depth):
        st = os.lstat(path)
        is_dir = os.path.isdir(path) and not os.path.islink(path)
        out.append((depth, path, st.st_size, is_dir))
        if is_dir:
            with os.scandir(path) as it:
                names = [e.name for e in it]   # scandir order == readdir order
            for n in names:
                walk(os.path.join(path, n), depth+1)
    walk(root, 0)
    return out

def simulate(roots, variant):
    (order, setmode, initmode, flushmode, shared) = variant
    sizes = {}
    def run(entries, state):
        cur, stack, prev_depth, parents = state
        # parents: stack of node names for current parent chain
        parent_chain = []  # list of node names; parent_chain[-1] is parent of current level
        node_own = {}
        prev_node = None
        for (depth, name, own, is_dir) in entries:
            fs = own
            node_own[name] = own
            if depth > prev_depth:
                stack.append(cur)
                if initmode == 'child': cur = fs
                elif initmode == 'own+child': cur = prev_fs + fs
                elif initmode == 'zero': cur = fs
                parent_chain.append(prev_node)
            elif depth < prev_depth:
                for _ in range(depth, prev_depth):
                    p = parent_chain.pop()
                    if order == 'set,pop,add':
                        sizes[p] = (cur if setmode=='replace' else cur + node_own[p])
                        d = stack.pop(); cur += d
                    elif order == 'pop,add,set':
                        d = stack.pop(); cur += d
                        sizes[p] = (cur if setmode=='replace' else cur + node_own[p])
                    elif order == 'pop,set,add':
                        d = stack.pop()
                        sizes[p] = (cur if setmode=='replace' else cur + node_own[p])
                        cur += d
                cur += fs
            else:
                cur += fs
            prev_depth = depth
            prev_node = name
            prev_fs = fs
        # flush
        if flushmode == 'loop':
            while parent_chain:
                p = parent_chain.pop()
                if order == 'set,pop,add':
                    sizes[p] = (cur if setmode=='replace' else cur + node_own[p]); d = stack.pop(); cur += d
                elif order == 'pop,add,set':
