                elif order == 'pop,set,add':
                    d = stack.pop(); sizes[p] = (cur if setmode=='replace' else cur + node_own[p]); cur += d
        return (cur, stack, 0, None)
    state = (0, [], 0, None)
    for r in roots:
        entries = build_entries(r)
        if not shared: state = (0, [], 0, None)
        state = run(entries, state)
    return sizes

