//! Byte count formatting in the various user selectable units.
use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ByteFormat {
    Metric,
    Binary,
    Bytes,
    GB,
    GiB,
    MB,
    MiB,
}

impl ByteFormat {
    pub const ALL: [ByteFormat; 7] = [
        ByteFormat::Metric,
        ByteFormat::Binary,
        ByteFormat::Bytes,
        ByteFormat::GB,
        ByteFormat::GiB,
        ByteFormat::MB,
        ByteFormat::MiB,
    ];

    pub fn name(&self) -> &'static str {
        match self {
            ByteFormat::Metric => "metric",
            ByteFormat::Binary => "binary",
            ByteFormat::Bytes => "bytes",
            ByteFormat::GB => "gb",
            ByteFormat::GiB => "gib",
            ByteFormat::MB => "mb",
            ByteFormat::MiB => "mib",
        }
    }

    pub fn from_name(name: &str) -> Option<ByteFormat> {
        ByteFormat::ALL
            .iter()
            .copied()
            .find(|f| f.name().eq_ignore_ascii_case(name))
    }

    /// The width of the column that fits all possible values of this format.
    pub fn width(&self) -> usize {
        match self {
            ByteFormat::Metric => 10,
            ByteFormat::Binary => 11,
            ByteFormat::Bytes => 12,
            ByteFormat::GB | ByteFormat::GiB => 10,
            ByteFormat::MB | ByteFormat::MiB => 12,
        }
    }

    /// The width of the unit field.
    pub fn unit_width(&self) -> usize {
        match self {
            ByteFormat::Binary | ByteFormat::GiB | ByteFormat::MiB => 3,
            ByteFormat::Metric | ByteFormat::GB | ByteFormat::MB => 2,
            ByteFormat::Bytes => 1,
        }
    }

    pub fn display(&self, bytes: u128) -> ByteFormatDisplay {
        ByteFormatDisplay {
            format: *self,
            bytes,
        }
    }

    /// Formats the value right-aligned into a column of `width()` characters.
    pub fn column(&self, bytes: u128) -> String {
        format!("{:>width$}", self.display(bytes).to_string(), width = self.width())
    }
}

const KB: u128 = 1000;
const MB_: u128 = 1000 * KB;
const GB_: u128 = 1000 * MB_;
const TB: u128 = 1000 * GB_;
const PB: u128 = 1000 * TB;
const EB: u128 = 1000 * PB;
const ZB: u128 = 1000 * EB;

const KIB: u128 = 1024;
const MIB_: u128 = 1024 * KIB;
const GIB_: u128 = 1024 * MIB_;
const TIB: u128 = 1024 * GIB_;
const PIB: u128 = 1024 * TIB;
const EIB: u128 = 1024 * PIB;
const ZIB: u128 = 1024 * EIB;

