        if bytes > *unit_bytes {
            return (bytes as f64 / *unit_bytes as f64, unit);
        }
    }
    (bytes as f64, "B")
}

pub struct ByteFormatDisplay {
    format: ByteFormat,
    bytes: u128,
}

impl fmt::Display for ByteFormatDisplay {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
