//! A parallel directory walker which yields entries in depth-first order,
//! while reading directories concurrently in a thread pool.
use std::collections::HashSet;
use std::ffi::OsString;
use std::fs::{self, Metadata};
use std::io;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::sync::{Arc, OnceLock};

use crossbeam_channel::{bounded, Receiver};

pub struct WalkOptions {
    pub threads: usize,
    pub apparent_size: bool,
    pub count_hard_links: bool,
    pub cross_filesystems: bool,
    /// Device and inode numbers of directories that should not be traversed into.
    pub ignore_dirs: HashSet<(u64, u64)>,
}

impl WalkOptions {
    /// The size of an entry as it should be counted.
    pub fn size_of(&self, m: &Metadata) -> u128 {
        if self.apparent_size {
            m.len() as u128
        } else {
            (m.blocks() as u128) * 512
        }
    }
}

/// Keeps track of inodes that were seen before, to not count hard links multiple times.
#[derive(Default)]
pub struct InodeFilter {
    inodes: HashSet<(u64, u64)>,
}

impl InodeFilter {
    /// Returns true if the entry described by `m` should be counted.
    pub fn add(&mut self, m: &Metadata) -> bool {
        if m.nlink() > 1 {
            self.inodes.insert((m.dev(), m.ino()))
        } else {
            true
        }
    }
}

pub struct Entry {
    pub depth: usize,
    pub path: PathBuf,
    pub file_name: OsString,
    pub metadata: io::Result<Metadata>,
}

impl Entry {
    pub fn is_dir(&self) -> bool {
        self.metadata
            .as_ref()
            .map(|m| m.file_type().is_dir())
            .unwrap_or(false)
    }
}

struct Child {
    name: OsString,
    path: PathBuf,
    metadata: io::Result<Metadata>,
    children: Option<Receiver<Vec<Child>>>,
}

struct Context {
    options: Arc<WalkOptions>,
    root_device: u64,
}

static POOL: OnceLock<rayon::ThreadPool> = OnceLock::new();

fn pool(threads: usize) -> &'static rayon::ThreadPool {
    POOL.get_or_init(|| {
        rayon::ThreadPoolBuilder::new()
            .num_threads(threads)
            .thread_name(|i| format!("dua-walk-{}", i))
            .build()
            .expect("thread pool can be created")
    })
}

fn should_descend(ctx: &Context, m: &Metadata) -> bool {
    if !m.file_type().is_dir() {
        return false;
    }
    if ctx.options.ignore_dirs.contains(&(m.dev(), m.ino())) {
        return false;
    }
    if !ctx.options.cross_filesystems && m.dev() != ctx.root_device {
        return false;
    }
    true
}

fn spawn_read_dir(ctx: Arc<Context>, path: PathBuf) -> Receiver<Vec<Child>> {
    let (tx, rx) = bounded(1);
    rayon::spawn(move || {
        let children = read_dir(&ctx, &path);
        tx.send(children).ok();
    });
    rx
}

fn read_dir(ctx: &Arc<Context>, path: &Path) -> Vec<Child> {
    let iter = match fs::read_dir(path) {
        Ok(iter) => iter,
        Err(_) => return Vec::new(),
    };
    let mut children = Vec::new();
    for entry in iter {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };
        let name = entry.file_name();
        let child_path = path.join(&name);
        let metadata = fs::symlink_metadata(&child_path);
        let descend = metadata
            .as_ref()
            .map(|m| should_descend(ctx, m))
            .unwrap_or(false);
        let rx = if descend {
            Some(spawn_read_dir(Arc::clone(ctx), child_path.clone()))
        } else {
            None
        };
        children.push(Child {
            name,
            path: child_path,
            metadata,
            children: rx,
        });
    }
    children
}

/// Walk the given `root` and call `f` for each entry in depth-first order.
/// `f` returns false to abort the walk.
pub fn walk<F>(root: &Path, root_device: u64, options: &Arc<WalkOptions>, mut f: F)
where
    F: FnMut(Entry) -> bool,
{
    let ctx = Arc::new(Context {
        options: Arc::clone(options),
        root_device,
    });
    let root_metadata = fs::symlink_metadata(root);
    // Follow a symlink root to see if it points to a directory to traverse.
    let descend = match fs::metadata(root) {
        Ok(m) => should_descend(&ctx, &m),
        Err(_) => false,
    };
    let file_name = root
        .file_name()
        .map(|n| n.to_os_string())
        .unwrap_or_else(|| root.as_os_str().to_os_string());
    if !f(Entry {
        depth: 0,
        path: root.to_path_buf(),
        file_name,
        metadata: root_metadata,
    }) {
        return;
    }
    if !descend {
        return;
    }
    let pool = pool(options.threads);
    let (tx, rx) = bounded(1);
    let ctx2 = Arc::clone(&ctx);
    let root_path = root.to_path_buf();
    pool.spawn(move || {
        let children = read_dir(&ctx2, &root_path);
        tx.send(children).ok();
    });
    let children = rx.recv().unwrap_or_default();
    consume(children, 1, &mut f);
}

fn consume<F>(children: Vec<Child>, depth: usize, f: &mut F) -> bool
where
    F: FnMut(Entry) -> bool,
{
    for child in children {
        let Child {
            name,
            path,
            metadata,
            children,
        } = child;
        if !f(Entry {
            depth,
            path,
            file_name: name,
            metadata,
        }) {
            return false;
        }
        if let Some(rx) = children {
            let grand_children = rx.recv().unwrap_or_default();
            if !consume(grand_children, depth + 1, f) {
                return false;
            }
        }
    }
    true
}
EOF
echo ok"}

