//! The non-interactive mode which prints the aggregated size of each input path.
use std::fs;
use std::io::{self, IsTerminal, Write};
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::time::Duration;

use crate::byte_format::ByteFormat;
use crate::walk::{self, InodeFilter, WalkOptions};

#[derive(Debug, Default)]
pub struct Statistics {
    pub entries_traversed: u64,
    pub smallest_file_in_bytes: u128,
    pub largest_file_in_bytes: u128,
}

/// Periodically allows an action to be performed.
pub struct Throttle {
    trigger: Arc<AtomicBool>,
}

impl Throttle {
    pub fn new(interval: Duration, initial_sleep: Option<Duration>) -> Self {
        let trigger = Arc::new(AtomicBool::new(false));
        let flag = Arc::clone(&trigger);
        std::thread::spawn(move || {
            if let Some(initial) = initial_sleep {
                std::thread::sleep(initial);
            }
            loop {
                if Arc::strong_count(&flag) == 1 {
                    break;
                }
                flag.store(true, Ordering::Relaxed);
                std::thread::sleep(interval);
            }
        });
        Throttle { trigger }
    }

    pub fn throttled<F: FnOnce()>(&self, f: F) {
        if self.trigger.swap(false, Ordering::Relaxed) {
            f()
        }
    }
}

pub struct AggregateOptions {
    pub byte_format: ByteFormat,
    pub statistics: bool,
    pub sort_by_size: bool,
    pub compute_total: bool,
}

fn is_regular_file(path: &Path) -> bool {
    fs::metadata(path).map(|m| m.is_file()).unwrap_or(false)
}

fn write_path(
    out: &mut impl Write,
    byte_format: ByteFormat,
    path: &Path,
    num_bytes: u128,
    num_errors: u64,
    cyan: bool,
) -> io::Result<()> {
    let bytes = byte_format.column(num_bytes);
    let path = path.display().to_string();
    let path = if cyan {
        format!("\x1b[36m{}\x1b[39m", path)
    } else {
        path
    };
    writeln!(
        out,
        "\x1b[32m{}\x1b[39m {}{}",
        bytes,
        path,
        if num_errors == 0 {
            String::new()
        } else {
            format!(
                "  <{} IO Error{}>",
                num_errors,
                if num_errors > 1 { "s" } else { "" }
            )
        }
    )
}

/// Aggregate the given paths and print the result. Returns the amount of IO errors encountered.
pub fn aggregate(
    walk_options: Arc<WalkOptions>,
    options: AggregateOptions,
    paths: Vec<PathBuf>,
) -> io::Result<u64> {
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    let stderr = io::stderr();
    let mut err = if stderr.is_terminal() {
        Some(stderr)
    } else {
        None
    };
    let progress = Throttle::new(Duration::from_millis(100), Some(Duration::from_secs(1)));

    let mut stats = Statistics {
        entries_traversed: 0,
        smallest_file_in_bytes: u128::MAX,
        largest_file_in_bytes: 0,
    };
    let mut inodes = InodeFilter::default();
    let mut total_bytes: u128 = 0;
    let mut total_errors: u64 = 0;
    let mut aggregates: Vec<(PathBuf, u128, u64)> = Vec::new();
    let num_roots = paths.len();

    for path in paths {
        let mut num_bytes: u128 = 0;
        let mut num_errors: u64 = 0;
        let device_id = match fs::metadata(&path) {
            Ok(m) => Some(m.dev()),
            Err(_) => {
                num_errors += 1;
                None
            }
        };
        if let Some(device_id) = device_id {
            walk::walk(&path, device_id, &walk_options, |entry| {
                stats.entries_traversed += 1;
                if let Some(err) = err.as_mut() {
                    progress.throttled(|| {
                        write!(err, "Enumerating {} items\r", stats.entries_traversed).ok();
                        err.flush().ok();
                    });
                }
                match entry.metadata {
                    Ok(ref m) => {
                        let size = if (walk_options.count_hard_links || inodes.add(m))
                            && (walk_options.cross_filesystems || m.dev() == device_id)
                        {
                            walk_options.size_of(m)
                        } else {
                            0
                        };
                        stats.largest_file_in_bytes = stats.largest_file_in_bytes.max(size);
                        stats.smallest_file_in_bytes = stats.smallest_file_in_bytes.min(size);
                        num_bytes += size;
                    }
                    Err(_) => num_errors += 1,
                }
                true
            });
        }
        if let Some(err) = err.as_mut() {
            write!(err, "\x1b[2K\r").ok();
            err.flush().ok();
        }
        total_bytes += num_bytes;
        total_errors += num_errors;
        if options.sort_by_size {
            aggregates.push((path, num_bytes, num_errors));
        } else {
            let cyan = !is_regular_file(&path);
            write_path(
                &mut out,
                options.byte_format,
                &path,
                num_bytes,
                num_errors,
                cyan,
            )?;
        }
    }

    if options.sort_by_size {
        aggregates.sort_by_key(|(_, bytes, _)| *bytes);
        for (path, num_bytes, num_errors) in aggregates {
            let cyan = !is_regular_file(&path);
            write_path(
                &mut out,
                options.byte_format,
                &path,
                num_bytes,
                num_errors,
                cyan,
            )?;
        }
    }

    if num_roots > 1 && options.compute_total {
        write_path(
            &mut out,
            options.byte_format,
            Path::new("total"),
            total_bytes,
            total_errors,
            false,
        )?;
    }
    out.flush()?;

    if options.statistics {
        if stats.smallest_file_in_bytes == u128::MAX {
            stats.smallest_file_in_bytes = 0;
        }
        eprintln!("{:?}", stats);
    }
    Ok(total_errors)
}
