fn parse_args() -> Args {
    let matches = command().get_matches();
    let paths = |m: &clap::ArgMatches, name: &str| -> Vec<PathBuf> {
        m.get_many::<PathBuf>(name)
            .map(|v| v.cloned().collect())
            .unwrap_or_default()
    };
    let command = match matches.subcommand() {
        Some(("interactive", sub)) => Some(SubCommand::Interactive {
            no_entry_check: sub.get_flag("no-entry-check"),
            input: paths(sub, "input"),
        }),
        Some(("aggregate", sub)) => Some(SubCommand::Aggregate {
            statistics: sub.get_flag("stats"),
            no_sort: sub.get_flag("no-sort"),
            no_total: sub.get_flag("no-total"),
            input: paths(sub, "input"),
        }),
        Some(("completions", sub)) => Some(SubCommand::Completions {
            shell: *sub.get_one::<Shell>("shell").expect("required"),
        }),
        _ => None,
    };
    Args {
        command,
        threads: *matches.get_one::<usize>("threads").expect("default"),
        format: *matches.get_one::<ByteFormat>("format").expect("default"),
        apparent_size: matches.get_flag("apparent-size"),
        count_hard_links: matches.get_flag("count-hard-links"),
        stay_on_filesystem: matches.get_flag("stay-on-filesystem"),
        ignore_dirs: paths(&matches, "ignore-dirs"),
        input: paths(&matches, "input"),
        log_file: matches.get_one::<PathBuf>("log-file").cloned(),
    }
}

/// Make the path absolute and resolve `.` and `..` components lexically.
fn absolutize(path: &Path) -> PathBuf {
    let mut result = if path.is_absolute() {
        PathBuf::new()
    } else {
        env::current_dir().unwrap_or_default()
    };
    for component in path.components() {
        match component {
            Component::CurDir => {}
            Component::ParentDir => {
                result.pop();
            }
            Component::RootDir => result.push("/"),
            Component::Prefix(_) => {}
            Component::Normal(c) => result.push(c),
        }
    }
    result
}

fn canonicalize_ignore_dirs(dirs: &[PathBuf]) -> BTreeSet<PathBuf> {
    dirs.iter()
        .map(|p| {
            fs::canonicalize(p).unwrap_or_else(|_| {
                let abs = absolutize(p);
                fs::canonicalize(&abs).unwrap_or(abs)
            })
        })
        .collect()
}

fn ignore_dir_ids(dirs: &BTreeSet<PathBuf>) -> HashSet<(u64, u64)> {
    dirs.iter()
        .filter_map(|p| fs::metadata(p).ok())
        .filter(|m| m.is_dir())
        .map(|m| (m.dev(), m.ino()))
        .collect()
}

/// Determine the paths to traverse. A single directory is entered and its entries become the roots.
fn paths_to_traverse(input: Vec<PathBuf>, stay_on_filesystem: bool) -> Result<Vec<PathBuf>> {
    let expand_cwd = match input.as_slice() {
        [] => true,
        [single] if single.is_dir() => {
            env::set_current_dir(single).with_context(|| {
                format!("Failed to change directory to '{}'", single.display())
            })?;
            true
        }
        _ => false,
    };
    if !expand_cwd {
        return Ok(input);
    }
    let cwd = env::current_dir()?;
    let cwd_device = fs::metadata(&cwd)?.dev();
    let mut entries = Vec::new();
    for entry in fs::read_dir(&cwd)? {
        let entry = entry?;
        let metadata = entry.metadata()?;
        if metadata.file_type().is_symlink() {
            continue;
        }
        if stay_on_filesystem && metadata.dev() != cwd_device {
            continue;
        }
        entries.push(PathBuf::from(entry.file_name()));
    }
    entries.sort();
    Ok(entries)
}

fn run() -> Result<ExitCode> {
    let args = parse_args();
    if let Some(log_file) = &args.log_file {
        logging::init(log_file)?;
    }
    logging::info(&format!("dua options={:#?}", args));

    let ignore_dirs = canonicalize_ignore_dirs(&args.ignore_dirs);
    logging::info(&format!("Ignoring canonicalized {:?}", ignore_dirs));

    let walk_options = Arc::new(WalkOptions {
        threads: args.threads,
        apparent_size: args.apparent_size,
        count_hard_links: args.count_hard_links,
        cross_filesystems: !args.stay_on_filesystem,
        ignore_dirs: ignore_dir_ids(&ignore_dirs),
    });

    match args.command {
        Some(SubCommand::Completions { shell }) => {
            let mut cmd = command();
            clap_complete::generate(
                shell.to_complete_shell(),
                &mut cmd,
                "dua",
                &mut std::io::stdout(),
            );
            Ok(ExitCode::SUCCESS)
        }
        Some(SubCommand::Interactive {
            no_entry_check,
            input,
        }) => {
            if !std::io::stderr().is_terminal() {
                return Err(anyhow!("Interactive mode requires a connected terminal"));
            }
            let paths = paths_to_traverse(input, args.stay_on_filesystem)?;
            let res = interactive::run(
                walk_options,
                args.format,
                !no_entry_check,
                paths,
            )?;
            Ok(if res.success {
                ExitCode::SUCCESS
            } else {
                ExitCode::FAILURE
            })
        }
        Some(SubCommand::Aggregate {
            statistics,
            no_sort,
            no_total,
            input,
        }) => run_aggregate(walk_options, args.format, input, args.stay_on_filesystem, statistics, no_sort, no_total),
        None => run_aggregate(walk_options, args.format, args.input, args.stay_on_filesystem, false, false, false),
    }
}

fn run_aggregate(
    walk_options: Arc<WalkOptions>,
    format: ByteFormat,
    input: Vec<PathBuf>,
    stay_on_filesystem: bool,
    statistics: bool,
    no_sort: bool,
    no_total: bool,
) -> Result<ExitCode> {
    let paths = paths_to_traverse(input, stay_on_filesystem)?;
    let errors = aggregate::aggregate(
        walk_options,
        aggregate::AggregateOptions {
            byte_format: format,
            statistics,
            sort_by_size: !no_sort,
            compute_total: !no_total,
        },
        paths,
    )?;
    Ok(if errors == 0 {
        ExitCode::SUCCESS
    } else {
        ExitCode::FAILURE
    })
}

fn main() -> ExitCode {
    match run() {
        Ok(code) => code,
        Err(err) => {
            eprintln!("Error: {}", err);
            ExitCode::FAILURE
        }
    }
}
