//! The tree of entries built by the traversal.
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

pub type TreeIndex = usize;

#[derive(Debug, Clone)]
pub struct EntryData {
    pub name: PathBuf,
    pub size: u128,
    pub mtime: SystemTime,
    /// The amount of entries in this directory (including itself), or `Some(0)` for entries that
    /// were not counted, or None if unknown.
    pub entry_count: Option<u64>,
    /// Set for entries that weren't counted (e.g. hard links seen before).
    pub is_dir: bool,
    pub metadata_io_error: bool,
}

impl Default for EntryData {
    fn default() -> Self {
        EntryData {
            name: PathBuf::new(),
            size: 0,
            mtime: UNIX_EPOCH,
            entry_count: None,
            is_dir: false,
            metadata_io_error: false,
        }
    }
}

#[derive(Debug)]
struct Node {
    data: EntryData,
    parent: Option<TreeIndex>,
    children: Vec<TreeIndex>,
}

#[derive(Debug, Default)]
pub struct Tree {
    nodes: Vec<Option<Node>>,
}

impl Tree {
    pub fn new() -> Self {
        Tree::default()
    }

    pub fn add_node(&mut self, data: EntryData) -> TreeIndex {
        self.nodes.push(Some(Node {
            data,
            parent: None,
            children: Vec::new(),
        }));
        self.nodes.len() - 1
    }

    pub fn add_edge(&mut self, parent: TreeIndex, child: TreeIndex) {
        if let Some(Some(node)) = self.nodes.get_mut(child) {
            node.parent = Some(parent);
        }
        if let Some(Some(node)) = self.nodes.get_mut(parent) {
            node.children.push(child);
        }
    }

    pub fn contains(&self, idx: TreeIndex) -> bool {
        matches!(self.nodes.get(idx), Some(Some(_)))
    }

    pub fn get(&self, idx: TreeIndex) -> Option<&EntryData> {
        self.nodes.get(idx).and_then(|n| n.as_ref()).map(|n| &n.data)
    }

    pub fn get_mut(&mut self, idx: TreeIndex) -> Option<&mut EntryData> {
        self.nodes
            .get_mut(idx)
            .and_then(|n| n.as_mut())
            .map(|n| &mut n.data)
    }

    pub fn parent(&self, idx: TreeIndex) -> Option<TreeIndex> {
        self.nodes.get(idx).and_then(|n| n.as_ref()).and_then(|n| n.parent)
    }

    /// Children in insertion order.
    pub fn children(&self, idx: TreeIndex) -> &[TreeIndex] {
        self.nodes
            .get(idx)
            .and_then(|n| n.as_ref())
            .map(|n| n.children.as_slice())
            .unwrap_or(&[])
    }

    pub fn has_children(&self, idx: TreeIndex) -> bool {
        !self.children(idx).is_empty()
    }

    /// Remove the node and all of its descendants. Returns the removed indices.
    pub fn remove_subtree(&mut self, idx: TreeIndex) -> Vec<TreeIndex> {
        let mut removed = Vec::new();
        if let Some(parent) = self.parent(idx) {
            if let Some(Some(p)) = self.nodes.get_mut(parent) {
                p.children.retain(|&c| c != idx);
            }
        }
        let mut stack = vec![idx];
        while let Some(i) = stack.pop() {
            if let Some(slot) = self.nodes.get_mut(i) {
                if let Some(node) = slot.take() {
                    stack.extend(node.children.iter().copied());
                    removed.push(i);
                }
            }
        }
        removed
    }

    /// Remove all children of a node, keeping the node itself.
    pub fn remove_children(&mut self, idx: TreeIndex) {
        let children: Vec<TreeIndex> = self.children(idx).to_vec();
        for c in children {
            self.remove_subtree(c);
        }
    }

    /// The path of a node, built from the names of all of its ancestors below `stop_at`.
    pub fn path_of(&self, idx: TreeIndex, stop_at: TreeIndex) -> PathBuf {
        let mut names = Vec::new();
        let mut cur = Some(idx);
        while let Some(i) = cur {
            if i == stop_at {
                break;
            }
            match self.nodes.get(i).and_then(|n| n.as_ref()) {
                Some(node) => {
                    names.push(node.data.name.as_path());
                    cur = node.parent;
                }
                None => break,
            }
        }
        let mut path = PathBuf::new();
        for name in names.iter().rev() {
            path.push(name);
        }
        path
    }

    /// Whether `ancestor` is an ancestor of (or equal to) `idx`.
    pub fn is_ancestor_or_self(&self, ancestor: TreeIndex, idx: TreeIndex) -> bool {
        let mut cur = Some(idx);
        while let Some(i) = cur {
            if i == ancestor {
                return true;
            }
            cur = self.parent(i);
        }
        false
    }

    /// All descendants of a node in depth-first order (not including the node itself).
    pub fn descendants(&self, idx: TreeIndex) -> Vec<TreeIndex> {
        let mut out = Vec::new();
        let mut stack: Vec<TreeIndex> = self.children(idx).iter().rev().copied().collect();
        while let Some(i) = stack.pop() {
            out.push(i);
            stack.extend(self.children(i).iter().rev().copied());
        }
        out
    }
}

pub fn display_path(path: &Path) -> String {
    path.display().to_string()
}
