    pub fn start(
        walk_options: Arc<WalkOptions>,
        roots: Vec<PathBuf>,
        parent_of_roots: TreeIndex,
        traversal: &mut Traversal,
    ) -> Self {
        let (tx, rx) = bounded::<TraversalEvent>(4096);
        traversal.entries_traversed = 0;
        traversal.start = Instant::now();
        traversal.elapsed = None;
        let thread = std::thread::spawn(move || {
            let mut inodes = InodeFilter::default();
            let mut io_errors = 0u64;
            'roots: for root in roots {
                logging::info(&format!("Walking {:?}", root));
