                        .send(TraversalEvent::Entry {
                            depth: entry.depth,
                            name,
                            meta,
                        })
                        .is_err()
                    {
                        aborted = true;
                        return false;
                    }
                    true
                });
                if aborted {
                    break 'roots;
                }
            }
            tx.send(TraversalEvent::Finished { io_errors }).ok();
        });
