            receiver: rx,
            _thread: thread,
            parent_of_roots,
            current_directory_at_depth: EntryInfo::default(),
            directory_info_per_depth_level: Vec::new(),
            previous_depth: 0,
            parent_node_idx: parent_of_roots,
            previous_node_idx: parent_of_roots,
            directory_own_size: 0,
            is_done: false,
        }
    }

    /// Integrate pending events. Returns true if anything changed.
    pub fn integrate_pending(&mut self, traversal: &mut Traversal, budget: Duration) -> bool {
        let start = Instant::now();
        let mut changed = false;
        loop {
            match self.receiver.try_recv() {
                Ok(event) => {
                    changed = true;
                    if self.integrate(traversal, event) {
                        self.is_done = true;
                        break;
                    }
                }
                Err(_) => break,
            }
