    pub fn wait_and_integrate(&mut self, traversal: &mut Traversal, timeout: Duration) -> bool {
        match self.receiver.recv_timeout(timeout) {
            Ok(event) => {
                if self.integrate(traversal, event) {
                    self.is_done = true;
                } else {
                    self.integrate_pending(traversal, Duration::from_millis(50));
                    if !self.is_done {
