                        } else {
                            data.entry_count = Some(0);
                            data.is_dir = true;
                            (0, 0)
                        }
                    }
                    Err(()) => {
                        data.metadata_io_error = true;
                        (0, 0)
                    }
                };
                data.size = size;
                match depth.cmp(&self.previous_depth) {
                    std::cmp::Ordering::Greater => {
                        self.directory_info_per_depth_level
                            .push(self.current_directory_at_depth);
                        self.current_directory_at_depth = EntryInfo {
                            size,
                            entries_count: count,
                        };
                        self.parent_node_idx = self.previous_node_idx;
                        self.directory_own_size = traversal
                            .tree
                            .get(self.parent_node_idx)
                            .map(|d| d.size)
                            .unwrap_or(0);
                    }
                    std::cmp::Ordering::Less => {
                        for _ in depth..self.previous_depth {
                            self.close_directory(traversal, true);
                        }
                        self.current_directory_at_depth.size += size;
                        self.current_directory_at_depth.entries_count += count;
                    }
                    std::cmp::Ordering::Equal => {
                        self.current_directory_at_depth.size += size;
                        self.current_directory_at_depth.entries_count += count;
                    }
                }
                let entry_index = traversal.tree.add_node(data);
                traversal.tree.add_edge(self.parent_node_idx, entry_index);
                self.previous_node_idx = entry_index;
                self.previous_depth = depth;
                false
            }
            TraversalEvent::Finished { io_errors } => {
                traversal.io_errors += io_errors;
                for _ in 0..self.previous_depth {
                    self.close_directory(traversal, false);
                }
                self.previous_depth = 0;
                traversal.recompute_ancestors(self.parent_of_roots);
                traversal.elapsed = Some(traversal.start.elapsed());
                true
            }
        }
    }
}
