//! Git-style glob matching (wildmatch), used by the interactive search.

#[derive(Debug, Clone)]
pub struct Pattern {
    text: Vec<u8>,
    /// Match against the whole relative path instead of just the base name.
    match_path: bool,
    /// Pattern only matches directories (trailing slash).
    dir_only: bool,
    case_insensitive: bool,
}

