    pub fn new(pattern: &str, case_insensitive: bool) -> Pattern {
        let mut text = pattern.as_bytes().to_vec();
        let mut dir_only = false;
        if text.len() > 1 && text.last() == Some(&b'/') {
            dir_only = true;
            text.pop();
        }
        let mut anchored = false;
        if text.first() == Some(&b'/') {
            anchored = true;
