use ratatui::backend::CrosstermBackend;
use ratatui::Terminal;

use crate::byte_format::ByteFormat;
use crate::walk::WalkOptions;
use app::App;

pub struct RunResult {
    pub success: bool,
}

const TICK: Duration = Duration::from_millis(250);

pub fn run(
    walk_options: Arc<WalkOptions>,
    byte_format: ByteFormat,
    entry_check: bool,
    paths: Vec<PathBuf>,
) -> Result<RunResult> {
    let mut stderr = io::stderr();
    enable_raw_mode()?;
    stderr.execute(EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(io::stderr());
    let mut terminal = Terminal::new(backend)?;
    terminal.hide_cursor()?;
    terminal.clear()?;

    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        main_loop(&mut terminal, walk_options, byte_format, entry_check, paths)
    }));

    terminal.show_cursor().ok();
    disable_raw_mode().ok();
    io::stderr().execute(LeaveAlternateScreen).ok();

    match result {
        Ok(res) => {
            let (app_result, marked) = res?;
            if !marked.is_empty() {
                use std::io::Write;
                let stdout = io::stdout();
                let mut out = stdout.lock();
                for path in marked {
                    writeln!(out, "{}", path)?;
                }
                out.flush()?;
            }
            Ok(app_result)
        }
        Err(payload) => std::panic::resume_unwind(payload),
    }
}

fn main_loop(
    terminal: &mut Terminal<CrosstermBackend<io::Stderr>>,
    walk_options: Arc<WalkOptions>,
    byte_format: ByteFormat,
    entry_check: bool,
    paths: Vec<PathBuf>,
) -> Result<(RunResult, Vec<String>)> {
    let mut app = App::new(walk_options, byte_format, entry_check);
    app.start_initial_traversal(paths);

    let (key_tx, key_rx) = unbounded::<Event>();
    std::thread::spawn(move || loop {
        match event::read() {
            Ok(ev) => {
                if key_tx.send(ev).is_err() {
                    break;
                }
            }
            Err(_) => break,
        }
    });

    let mut needs_draw = true;
    let mut immediate = true;
    let mut last_draw = Instant::now() - TICK;
    loop {
        let now = Instant::now();
        if needs_draw && (immediate || now.duration_since(last_draw) >= TICK) {
            terminal.draw(|frame| app.render(frame))?;
            last_draw = Instant::now();
            needs_draw = false;
            immediate = false;
        }
        if app.should_quit {
            break;
        }
        if app.deletion_in_progress() {
            app.deletion_step();
            needs_draw = true;
            while let Ok(ev) = key_rx.try_recv() {
                if let Event::Key(key) = ev {
                    if app.handle_key_during_deletion(key) {
                        immediate = true;
                    }
                } else if let Event::Resize(..) = ev {
                    immediate = true;
                }
            }
            continue;
        }
        let wait = if needs_draw {
            TICK.saturating_sub(now.duration_since(last_draw))
        } else {
            Duration::from_secs(3600)
        };
        let bg_rx = app.background_receiver();
        match bg_rx {
            Some(rx) => {
                select! {
                    recv(key_rx) -> ev => {
                        if let Ok(ev) = ev {
                            app.handle_event(ev);
                            needs_draw = true;
                            immediate = true;
                        }
                    }
                    recv(rx) -> ev => {
                        if let Ok(ev) = ev {
                            app.integrate_background_event(ev);
                            app.integrate_pending_background(Duration::from_millis(30));
                            needs_draw = true;
                            if app.background_just_finished() {
                                immediate = true;
                            }
                        }
                    }
                    default(wait) => {}
                }
            }
            None => {
                select! {
                    recv(key_rx) -> ev => {
                        if let Ok(ev) = ev {
                            app.handle_event(ev);
                            needs_draw = true;
                            immediate = true;
                        }
                    }
                    default(wait) => {}
                }
            }
        }
    }
    let marked = app.marked_paths_for_output();
    Ok((
        RunResult {
            success: app.traversal.io_errors == 0,
        },
        marked,
    ))
}
