//! Application state and key handling of the interactive mode.
use std::collections::{HashMap, HashSet};
use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::{Duration, SystemTime};

use crossbeam_channel::Receiver;
use crossterm::event::{Event, KeyCode, KeyEvent, KeyEventKind, KeyModifiers};
use ratatui::Frame;

use super::tree::{EntryData, TreeIndex};
use super::widgets;
use crate::byte_format::ByteFormat;
use crate::glob::Pattern;
use crate::traverse::{BackgroundTraversal, Traversal, TraversalEvent};
use crate::trash;
use crate::walk::WalkOptions;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SortMode {
    SizeDescending,
    SizeAscending,
    MTimeDescending,
    MTimeAscending,
    CountDescending,
    CountAscending,
    NameAscending,
    NameDescending,
}

impl SortMode {
    pub fn label(&self) -> &'static str {
        match self {
            SortMode::SizeDescending => "size descending",
            SortMode::SizeAscending => "size ascending",
            SortMode::MTimeDescending => "modified descending",
            SortMode::MTimeAscending => "modified ascending",
            SortMode::CountDescending => "items descending",
            SortMode::CountAscending => "items ascending",
            SortMode::NameAscending => "name ascending",
            SortMode::NameDescending => "name descending",
        }
    }
    fn toggle_size(self) -> Self {
        match self {
            SortMode::SizeDescending => SortMode::SizeAscending,
            _ => SortMode::SizeDescending,
        }
    }
    fn toggle_mtime(self) -> Self {
        match self {
            SortMode::MTimeDescending => SortMode::MTimeAscending,
            _ => SortMode::MTimeDescending,
        }
    }
    fn toggle_count(self) -> Self {
        match self {
            SortMode::CountDescending => SortMode::CountAscending,
            _ => SortMode::CountDescending,
        }
    }
    fn toggle_name(self) -> Self {
        match self {
            SortMode::NameAscending => SortMode::NameDescending,
            _ => SortMode::NameAscending,
        }
    }
    pub fn is_mtime(&self) -> bool {
        matches!(self, SortMode::MTimeDescending | SortMode::MTimeAscending)
    }
    pub fn is_count(&self) -> bool {
        matches!(self, SortMode::CountDescending | SortMode::CountAscending)
    }
    pub fn is_size(&self) -> bool {
        matches!(self, SortMode::SizeDescending | SortMode::SizeAscending)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DisplayMode {
    PercentageAndBar,
    Percentage,
    Bar,
    LongBar,
}

impl DisplayMode {
    fn next(self) -> Self {
        match self {
            DisplayMode::PercentageAndBar => DisplayMode::Percentage,
            DisplayMode::Percentage => DisplayMode::Bar,
            DisplayMode::Bar => DisplayMode::LongBar,
            DisplayMode::LongBar => DisplayMode::PercentageAndBar,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Focus {
    Main,
    Help,
    Mark,
    Glob,
}

#[derive(Debug, Clone)]
pub struct EntryItem {
    pub index: TreeIndex,
    pub name: String,
    pub size: u128,
    pub mtime: SystemTime,
    pub entry_count: Option<u64>,
    pub is_dir: bool,
    pub exists: bool,
    pub metadata_io_error: bool,
}

pub struct GlobState {
    pub search_root: TreeIndex,
    pub results: Vec<TreeIndex>,
    pub active: bool,
    pub input: String,
    pub case_insensitive: bool,
    pub pane_open: bool,
    /// Selection in the directory the search started from, to restore it when leaving.
    pub previous_selection: Option<TreeIndex>,
}

pub struct MarkPane {
    pub selected: Option<usize>,
    pub errors: HashMap<TreeIndex, u64>,
    pub list_offset: usize,
}

pub struct HelpPane {
    pub scroll: usize,
}

pub struct DeletionState {
    pub queue: Vec<TreeIndex>,
    pub deleted_items: u64,
    pub to_trash: bool,
}

pub struct App {
    pub walk_options: Arc<WalkOptions>,
    pub byte_format: ByteFormat,
    pub entry_check: bool,
    pub traversal: Traversal,
    background: Option<BackgroundTraversal>,
    background_finished_flag: bool,
    pub sorting: SortMode,
    pub show_mtime: bool,
    pub show_count: bool,
    pub display_mode: DisplayMode,
    /// The directory whose entries are shown, or None when showing glob results.
    pub view_root: Option<TreeIndex>,
    pub glob: Option<GlobState>,
    pub entries: Vec<EntryItem>,
    pub selected: Option<TreeIndex>,
    pub list_offset: usize,
    bookmarks: HashMap<TreeIndex, TreeIndex>,
    pub marked: Vec<TreeIndex>,
    marked_set: HashSet<TreeIndex>,
    pub mark_pane: Option<MarkPane>,
    pub help_pane: Option<HelpPane>,
    pub focus: Focus,
    pub message: Option<String>,
    pub quit_pending: bool,
    pub should_quit: bool,
    deletion: Option<DeletionState>,
    reselect_name: Option<PathBuf>,
    pub root_path: PathBuf,
    pub last_main_area_height: u16,
}

pub fn count_of(entry_count: Option<u64>) -> u64 {
    entry_count.unwrap_or(1)
}

impl App {
    pub fn new(walk_options: Arc<WalkOptions>, byte_format: ByteFormat, entry_check: bool) -> Self {
        let traversal = Traversal::new();
        let root = traversal.root_index;
        App {
            walk_options,
            byte_format,
            entry_check,
            traversal,
            background: None,
            background_finished_flag: false,
            sorting: SortMode::SizeDescending,
            show_mtime: false,
            show_count: false,
            display_mode: DisplayMode::PercentageAndBar,
            view_root: Some(root),
            glob: None,
            entries: Vec::new(),
            selected: None,
            list_offset: 0,
            bookmarks: HashMap::new(),
            marked: Vec::new(),
            marked_set: HashSet::new(),
            mark_pane: None,
            help_pane: None,
            focus: Focus::Main,
            message: None,
            quit_pending: false,
            should_quit: false,
            deletion: None,
            reselect_name: None,
            root_path: env::current_dir().unwrap_or_default(),
            last_main_area_height: 10,
        }
    }

    // ----- background traversal -------------------------------------------------------------

    pub fn start_initial_traversal(&mut self, paths: Vec<PathBuf>) {
        let root = self.traversal.root_index;
        self.background = Some(BackgroundTraversal::start(
            Arc::clone(&self.walk_options),
            paths,
            root,
            &mut self.traversal,
        ));
        self.message = None;
        self.recompute_entries();
    }

    fn start_refresh(&mut self, paths: Vec<PathBuf>, parent: TreeIndex) {
        self.background = Some(BackgroundTraversal::start(
            Arc::clone(&self.walk_options),
            paths,
            parent,
            &mut self.traversal,
        ));
        self.recompute_entries();
    }

    pub fn is_scanning(&self) -> bool {
        self.background.as_ref().map(|b| !b.is_done).unwrap_or(false)
    }

    pub fn background_receiver(&self) -> Option<Receiver<TraversalEvent>> {
        self.background
            .as_ref()
            .filter(|b| !b.is_done)
            .map(|b| b.receiver.clone())
    }

    pub fn integrate_background_event(&mut self, event: TraversalEvent) {
        if let Some(bg) = self.background.as_mut() {
            let finished = bg.integrate(&mut self.traversal, event);
            if finished {
                bg.is_done = true;
                self.on_background_finished();
            } else {
                self.traversal.recompute_root_size();
                self.message = Some("-> scanning <-".to_string());
                self.recompute_entries();
            }
        }
    }

    pub fn integrate_pending_background(&mut self, budget: Duration) {
        let start = std::time::Instant::now();
        loop {
            let event = match self.background.as_ref() {
                Some(bg) if !bg.is_done => match bg.receiver.try_recv() {
                    Ok(ev) => ev,
                    Err(_) => break,
                },
                _ => break,
            };
            self.integrate_background_event(event);
            if start.elapsed() > budget {
                break;
            }
        }
    }

    pub fn background_just_finished(&mut self) -> bool {
        std::mem::replace(&mut self.background_finished_flag, false)
    }

    fn on_background_finished(&mut self) {
        self.background = None;
        self.background_finished_flag = true;
        if self.message.as_deref() == Some("-> scanning <-") {
            self.message = None;
        }
        self.recompute_entries();
        if self.selected.is_none() {
            self.selected = self.entries.first().map(|e| e.index);
        }
        if let Some(name) = self.reselect_name.take() {
            if let Some(item) = self.entries.iter().find(|e| {
                self.traversal
                    .tree
                    .get(e.index)
                    .map(|d| d.name == name)
                    .unwrap_or(false)
            }) {
                self.selected = Some(item.index);
            }
        }
    }

    // ----- entries -------------------------------------------------------------------------

    pub fn path_of(&self, idx: TreeIndex) -> PathBuf {
        self.traversal.tree.path_of(idx, self.traversal.root_index)
    }

    pub fn recompute_entries(&mut self) {
        let tree = &self.traversal.tree;
        let do_check = self.entry_check && !self.is_scanning() && self.view_root.is_some();
        let indices: Vec<TreeIndex> = match self.view_root {
            Some(dir) => tree.children(dir).iter().rev().copied().collect(),
            None => self
                .glob
                .as_ref()
                .map(|g| g.results.clone())
                .unwrap_or_default(),
        };
        let mut items: Vec<EntryItem> = Vec::with_capacity(indices.len());
        for idx in indices {
            let Some(data) = tree.get(idx) else { continue };
            let name = match self.view_root {
                Some(_) => data.name.display().to_string(),
                None => self.path_of(idx).display().to_string(),
            };
            let (is_dir, exists) = if do_check {
                match fs::symlink_metadata(self.path_of(idx)) {
                    Ok(m) => (m.is_dir(), true),
                    Err(_) => (false, false),
                }
            } else {
                (data.is_dir, true)
            };
            items.push(EntryItem {
                index: idx,
                name,
                size: data.size,
                mtime: data.mtime,
                entry_count: data.entry_count,
                is_dir,
                exists,
                metadata_io_error: data.metadata_io_error,
            });
        }
        sort_entries(&mut items, self.sorting);
        self.entries = items;
        if let Some(sel) = self.selected {
            if !self.entries.iter().any(|e| e.index == sel) {
                self.selected = None;
            }
        }
        if self.selected.is_none() && !self.is_scanning() {
            self.selected = self.entries.first().map(|e| e.index);
        }
    }

    pub fn selected_position(&self) -> Option<usize> {
        let sel = self.selected?;
        self.entries.iter().position(|e| e.index == sel)
    }

    fn select_position(&mut self, pos: usize) {
        if self.entries.is_empty() {
            self.selected = None;
            return;
        }
        let pos = pos.min(self.entries.len() - 1);
        self.selected = Some(self.entries[pos].index);
    }

    fn move_selection(&mut self, delta: isize) {
        let Some(pos) = self.selected_position() else {
            return;
        };
        let new = if delta < 0 {
            pos.saturating_sub((-delta) as usize)
        } else {
            pos.saturating_add(delta as usize)
        };
        self.select_position(new);
    }

    pub fn view_title_path(&self) -> String {
        match self.view_root {
            Some(dir) if dir == self.traversal.root_index => self.root_path.display().to_string(),
            Some(dir) => self.path_of(dir).display().to_string(),
            None => self.root_path.display().to_string(),
        }
    }

    pub fn entries_total_size(&self) -> u128 {
        self.entries.iter().map(|e| e.size).sum()
    }

    pub fn entries_total_count(&self) -> u64 {
        self.entries.iter().map(|e| count_of(e.entry_count)).sum()
    }

    // ----- rendering ------------------------------------------------------------------------

    pub fn render(&mut self, frame: &mut Frame) {
        widgets::render(self, frame);
    }

    // ----- events ---------------------------------------------------------------------------

    pub fn handle_event(&mut self, event: Event) {
        match event {
            Event::Key(key) => self.handle_key(key),
            Event::Resize(..) => {}
            _ => {}
        }
    }

    pub fn handle_key_during_deletion(&mut self, key: KeyEvent) -> bool {
        if key.kind == KeyEventKind::Release {
            return false;
        }
        if key.modifiers.contains(KeyModifiers::CONTROL) && key.code == KeyCode::Char('c') {
            self.should_quit = true;
            return true;
        }
        false
    }

    fn handle_key(&mut self, key: KeyEvent) {
        if key.kind == KeyEventKind::Release {
            return;
        }
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        if ctrl && key.code == KeyCode::Char('c') {
            self.should_quit = true;
            return;
        }
        let had_quit_pending = self.quit_pending;
        self.quit_pending = false;
        if self.is_scanning() {
            self.message = None;
        } else {
            self.message = None;
        }
        match self.focus {
            Focus::Main => self.handle_main_key(key, had_quit_pending),
            Focus::Help => self.handle_help_key(key),
            Focus::Mark => self.handle_mark_key(key),
            Focus::Glob => self.handle_glob_key(key),
        }
        if self.is_scanning() && self.message.is_none() {
            // keep the scanning indicator unless another message replaced it
        }
    }

    fn cycle_focus(&mut self) {
        let order = [Focus::Main, Focus::Help, Focus::Mark, Focus::Glob];
        let available = |f: &Focus| match f {
            Focus::Main => true,
            Focus::Help => self.help_pane.is_some(),
            Focus::Mark => self.mark_pane.is_some(),
            Focus::Glob => self.glob.as_ref().map(|g| g.pane_open).unwrap_or(false),
        };
        let cur = order.iter().position(|f| *f == self.focus).unwrap_or(0);
        let mut next = self.focus;
        for i in 1..=order.len() {
            let candidate = order[(cur + i) % order.len()];
            if available(&candidate) {
                next = candidate;
                break;
            }
        }
        self.set_focus(next);
    }

    fn set_focus(&mut self, focus: Focus) {
        if self.focus == Focus::Mark && focus != Focus::Mark {
            // Leaving the mark pane through cycling clears its selection.
            if let Some(pane) = self.mark_pane.as_mut() {
                pane.selected = None;
            }
        }
        self.focus = focus;
        if focus == Focus::Mark {
            if let Some(pane) = self.mark_pane.as_mut() {
                pane.selected = Some(self.marked.len().saturating_sub(1));
            }
        }
    }

    fn quit_requested(&mut self, had_quit_pending: bool) {
        if !self.marked.is_empty() && !had_quit_pending {
            self.quit_pending = true;
        } else {
            self.should_quit = true;
        }
    }

    fn handle_main_key(&mut self, key: KeyEvent, had_quit_pending: bool) {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Esc | KeyCode::Char('q') => {
                if self.glob.as_ref().map(|g| g.active).unwrap_or(false) {
                    self.close_glob();
                } else {
                    self.quit_requested(had_quit_pending);
                }
            }
            KeyCode::Tab => self.cycle_focus(),
            KeyCode::Char('?') => self.toggle_help(),
            KeyCode::Char('/') => self.open_glob_pane(),
            KeyCode::Char('j') | KeyCode::Down => self.move_selection(1),
            KeyCode::Char('k') | KeyCode::Up => self.move_selection(-1),
            KeyCode::Char('d') if ctrl => self.move_selection(10),
            KeyCode::PageDown => self.move_selection(10),
            KeyCode::Char('u') if ctrl => self.move_selection(-10),
            KeyCode::PageUp => self.move_selection(-10),
            KeyCode::Char('H') | KeyCode::Home => self.select_position(0),
            KeyCode::Char('G') | KeyCode::End => {
                let last = self.entries.len().saturating_sub(1);
                self.select_position(last)
            }
            KeyCode::Char('o') | KeyCode::Char('l') | KeyCode::Enter | KeyCode::Right => {
                self.enter_selected()
            }
            KeyCode::Char('u') | KeyCode::Char('h') | KeyCode::Left | KeyCode::Backspace => {
                self.go_up()
            }
            KeyCode::Char('s') => self.set_sorting(self.sorting.toggle_size()),
            KeyCode::Char('m') => self.set_sorting(self.sorting.toggle_mtime()),
            KeyCode::Char('c') => self.set_sorting(self.sorting.toggle_count()),
            KeyCode::Char('n') => self.set_sorting(self.sorting.toggle_name()),
            KeyCode::Char('M') => self.show_mtime = !self.show_mtime,
            KeyCode::Char('C') => self.show_count = !self.show_count,
            KeyCode::Char('g') | KeyCode::Char('S') => {
                self.display_mode = self.display_mode.next()
            }
            KeyCode::Char('O') => self.open_selected(),
            KeyCode::Char('d') => {
                self.toggle_mark_selected(false);
                self.move_selection(1);
            }
            KeyCode::Char('x') => {
                self.toggle_mark_selected(true);
                self.move_selection(1);
            }
            KeyCode::Char(' ') => self.toggle_mark_selected(false),
            KeyCode::Char('a') => self.toggle_mark_all(),
            KeyCode::Char('r') => self.refresh_selected(),
            KeyCode::Char('R') => self.refresh_all(),
            _ => {}
        }
    }

    fn set_sorting(&mut self, mode: SortMode) {
        self.sorting = mode;
        self.recompute_entries();
    }

    fn enter_selected(&mut self) {
        let Some(sel) = self.selected else {
            return;
        };
        if !self.traversal.tree.has_children(sel) {
            self.message = Some("Entry is a file or an empty directory".to_string());
            return;
        }
        if let Some(dir) = self.view_root {
            self.bookmarks.insert(dir, sel);
        }
        self.view_root = Some(sel);
        self.selected = self.bookmarks.get(&sel).copied();
        self.list_offset = 0;
        self.recompute_entries();
    }

    fn go_up(&mut self) {
        let Some(dir) = self.view_root else {
            self.message = Some("Top level reached".to_string());
            return;
        };
        if dir == self.traversal.root_index {
            self.message = Some("Top level reached".to_string());
            return;
        }
        if let Some(sel) = self.selected {
            self.bookmarks.insert(dir, sel);
        }
        let in_glob = self
            .glob
            .as_ref()
            .map(|g| g.active && g.results.contains(&dir))
            .unwrap_or(false);
        if in_glob {
            self.view_root = None;
        } else {
            self.view_root = self.traversal.tree.parent(dir);
        }
        self.selected = Some(dir);
        self.list_offset = 0;
        self.recompute_entries();
    }

    fn toggle_help(&mut self) {
        if self.help_pane.is_some() {
            self.help_pane = None;
            if self.focus == Focus::Help {
                self.focus = Focus::Main;
            }
        } else {
            self.help_pane = Some(HelpPane { scroll: 0 });
            self.set_focus(Focus::Help);
        }
    }

    fn open_glob_pane(&mut self) {
        match self.glob.as_mut() {
            Some(g) => g.pane_open = true,
            None => {
                let search_root = self.view_root.unwrap_or(self.traversal.root_index);
                self.glob = Some(GlobState {
                    search_root,
                    results: Vec::new(),
                    active: false,
                    input: String::new(),
                    case_insensitive: true,
                    pane_open: true,
                    previous_selection: self.selected,
                });
            }
        }
        self.set_focus(Focus::Glob);
    }

    fn close_glob(&mut self) {
        if let Some(g) = self.glob.take() {
            if g.active || self.view_root.is_none() {
                self.view_root = Some(g.search_root);
                self.selected = g.previous_selection;
                self.list_offset = 0;
                self.recompute_entries();
            }
        }
        if self.focus == Focus::Glob {
            self.focus = Focus::Main;
        }
    }

    fn open_selected(&mut self) {
        let Some(sel) = self.selected else {
            return;
        };
        let path = self.path_of(sel);
        let _ = std::process::Command::new("xdg-open")
            .arg(&path)
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn();
    }

    // ----- marks ----------------------------------------------------------------------------

    pub fn is_marked(&self, idx: TreeIndex) -> bool {
        self.marked_set.contains(&idx)
    }

    fn add_mark(&mut self, idx: TreeIndex) {
        if self.marked_set.insert(idx) {
            self.marked.push(idx);
        }
        self.ensure_mark_pane();
        if let Some(pane) = self.mark_pane.as_mut() {
            pane.selected = None;
        }
    }

    fn remove_mark(&mut self, idx: TreeIndex) {
        if self.marked_set.remove(&idx) {
            self.marked.retain(|&i| i != idx);
        }
        if let Some(pane) = self.mark_pane.as_mut() {
            pane.errors.remove(&idx);
            if let Some(sel) = pane.selected {
                if !self.marked.is_empty() {
                    pane.selected = Some(sel.min(self.marked.len() - 1));
                }
            }
        }
        if self.marked.is_empty() {
            self.mark_pane = None;
            if self.focus == Focus::Mark {
                self.focus = Focus::Main;
            }
        }
    }

    fn ensure_mark_pane(&mut self) {
        if self.mark_pane.is_none() && !self.marked.is_empty() {
            self.mark_pane = Some(MarkPane {
                selected: None,
                errors: HashMap::new(),
                list_offset: 0,
            });
        }
    }

    fn toggle_mark_selected(&mut self, mark_only: bool) {
        let Some(sel) = self.selected else {
            return;
        };
        if self.is_marked(sel) {
            if !mark_only {
                self.remove_mark(sel);
            }
        } else {
            self.add_mark(sel);
        }
    }

    fn toggle_mark_all(&mut self) {
        let indices: Vec<TreeIndex> = self.entries.iter().map(|e| e.index).collect();
        for idx in indices {
            if self.is_marked(idx) {
                self.remove_mark(idx);
            } else {
                self.add_mark(idx);
            }
        }
    }

    pub fn marked_total(&self) -> (u64, u128) {
        let mut count = 0u64;
        let mut size = 0u128;
        for &idx in &self.marked {
            if let Some(d) = self.traversal.tree.get(idx) {
                count += count_of(d.entry_count);
                size += d.size;
            }
        }
        (count, size)
    }

    pub fn marked_paths_for_output(&self) -> Vec<String> {
        self.marked
            .iter()
            .map(|&idx| self.path_of(idx).display().to_string())
            .collect()
    }

    // ----- help pane keys -------------------------------------------------------------------

    pub fn help_text_len() -> usize {
        widgets::help_lines().len()
    }

    fn handle_help_key(&mut self, key: KeyEvent) {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        let max_scroll = Self::help_text_len().saturating_sub(self.last_help_height());
        let Some(pane) = self.help_pane.as_mut() else {
            return;
        };
        match key.code {
            KeyCode::Esc | KeyCode::Char('q') => {
                self.help_pane = None;
                self.focus = Focus::Main;
            }
            KeyCode::Char('?') => {
                self.help_pane = None;
                self.focus = Focus::Main;
            }
            KeyCode::Tab => self.cycle_focus(),
            KeyCode::Char('j') | KeyCode::Down => pane.scroll = (pane.scroll + 1).min(max_scroll),
            KeyCode::Char('k') | KeyCode::Up => pane.scroll = pane.scroll.saturating_sub(1),
            KeyCode::Char('d') if ctrl => pane.scroll = (pane.scroll + 10).min(max_scroll),
            KeyCode::PageDown => pane.scroll = (pane.scroll + 10).min(max_scroll),
            KeyCode::Char('u') if ctrl => pane.scroll = pane.scroll.saturating_sub(10),
            KeyCode::PageUp => pane.scroll = pane.scroll.saturating_sub(10),
            KeyCode::Char('H') | KeyCode::Home => pane.scroll = 0,
            KeyCode::Char('G') | KeyCode::End => pane.scroll = max_scroll,
            _ => {}
        }
    }

    pub last_help_height_cell: std::cell::Cell<usize>,
}
