            deleted_items: 0,
            to_trash,
        });
        self.message = Some("Deleted 0 items...".to_string());
    }

    /// Delete the next marked entry.
    pub fn deletion_step(&mut self) {
        let Some(state) = self.deletion.as_mut() else {
            return;
        };
        if state.queue.is_empty() {
            self.finish_deletion();
            return;
        }
        let idx = state.queue.remove(0);
        let to_trash = state.to_trash;
        if !self.traversal.tree.contains(idx) || !self.marked_set.contains(&idx) {
            return;
        }
        let path = self.path_of(idx);
        let count = self
            .traversal
            .tree
            .get(idx)
            .map(|d| count_of(d.entry_count))
            .unwrap_or(1);
        let errors = if to_trash {
            match trash::move_to_trash(&path) {
                Ok(()) => 0,
                Err(_) => 1,
            }
        } else {
            delete_recursively(&path)
        };
        if errors == 0 {
            let selected_pos = self.selected_position();
            let parent = self.traversal.tree.parent(idx);
            self.remove_nodes(&[idx]);
            if let Some(p) = parent {
                if self.traversal.tree.contains(p) {
                    self.traversal.recompute_ancestors(p);
                }
            }
            self.recompute_entries();
            if self.selected.is_none() {
                if let Some(pos) = selected_pos {
                    self.select_position(pos);
                }
            }
            if let Some(state) = self.deletion.as_mut() {
                state.deleted_items += count;
                self.message = Some(format!("Deleted {} items...", state.deleted_items));
            }
        } else if let Some(pane) = self.mark_pane.as_mut() {
            *pane.errors.entry(idx).or_insert(0) += errors;
        }
        if self
            .deletion
            .as_ref()
            .map(|s| s.queue.is_empty())
            .unwrap_or(true)
        {
            self.finish_deletion();
        }
    }

    fn finish_deletion(&mut self) {
        self.deletion = None;
        self.message = None;
        if self.marked.is_empty() {
            self.mark_pane = None;
            if self.focus == Focus::Mark {
                self.focus = Focus::Main;
            }
        }
        self.recompute_entries();
    }
}

/// Recursively delete a path, returning the number of errors encountered.
fn delete_recursively(path: &Path) -> u64 {
    let meta = match fs::symlink_metadata(path) {
        Ok(m) => m,
        Err(_) => return 1,
    };
    if meta.is_dir() {
        let mut errors = 0;
        match fs::read_dir(path) {
            Ok(iter) => {
                for entry in iter {
                    match entry {
                        Ok(entry) => errors += delete_recursively(&entry.path()),
                        Err(_) => errors += 1,
                    }
                }
            }
            Err(_) => errors += 1,
        }
        if fs::remove_dir(path).is_err() {
            errors += 1;
        }
        errors
    } else if fs::remove_file(path).is_err() {
        1
    } else {
        0
    }
}

pub fn sort_entries(items: &mut [EntryItem], mode: SortMode) {
    match mode {
        SortMode::SizeDescending => items.sort_by(|a, b| b.size.cmp(&a.size)),
        SortMode::SizeAscending => items.sort_by(|a, b| a.size.cmp(&b.size)),
        SortMode::MTimeDescending => items.sort_by(|a, b| b.mtime.cmp(&a.mtime)),
        SortMode::MTimeAscending => items.sort_by(|a, b| a.mtime.cmp(&b.mtime)),
        SortMode::CountDescending => items.sort_by(|a, b| {
            (b.entry_count, b.name.as_bytes()).cmp(&(a.entry_count, a.name.as_bytes()))
        }),
        SortMode::CountAscending => items.sort_by(|a, b| {
            (a.entry_count, a.name.as_bytes()).cmp(&(b.entry_count, b.name.as_bytes()))
        }),
        SortMode::NameAscending => items.sort_by(|a, b| {
            (!a.is_dir, a.name.as_bytes()).cmp(&(!b.is_dir, b.name.as_bytes()))
        }),
        SortMode::NameDescending => items.sort_by(|a, b| {
            (!b.is_dir, b.name.as_bytes()).cmp(&(!a.is_dir, a.name.as_bytes()))
        }),
    }
}

