    fn run_glob_search(&mut self) {
        let Some(g) = self.glob.as_ref() else {
            return;
        };
        let pattern = Pattern::new(&g.input, g.case_insensitive);
        let search_root = g.search_root;
        let tree = &self.traversal.tree;
        let mut results = Vec::new();
        // Depth-first search, not descending into matched directories.
        let mut stack: Vec<(TreeIndex, Vec<u8>)> = tree
            .children(search_root)
            .iter()
            .rev()
            .map(|&c| (c, Vec::new()))
            .collect();
        while let Some((idx, parent_rel)) = stack.pop() {
            let Some(data) = tree.get(idx) else { continue };
            let mut rel = parent_rel.clone();
            if !rel.is_empty() {
                rel.push(b'/');
            }
            rel.extend_from_slice(data.name.as_os_str().as_encoded_bytes());
            if pattern.matches(&rel) {
                results.push(idx);
                continue;
            }
            for &c in tree.children(idx).iter().rev() {
                stack.push((c, rel.clone()));
            }
        }
        if results.is_empty() {
            self.message = Some("No match found".to_string());
            return;
        }
        if let Some(g) = self.glob.as_mut() {
            g.results = results;
            g.active = true;
        }
        self.view_root = None;
        self.selected = None;
        self.list_offset = 0;
        self.focus = Focus::Main;
        self.recompute_entries();
    }

    // ----- refresh --------------------------------------------------------------------------

    fn refresh_selected(&mut self) {
        if self.is_scanning() {
            return;
        }
        let Some(sel) = self.selected else {
            return;
        };
        let Some(parent) = self.traversal.tree.parent(sel) else {
            return;
        };
        let path = self.path_of(sel);
        let name = self.traversal.tree.get(sel).map(|d| d.name.clone());
        self.remove_nodes(&[sel]);
        self.reselect_name = name;
        self.selected = None;
        self.start_refresh(vec![path], parent);
    }

    fn refresh_all(&mut self) {
        if self.is_scanning() {
            return;
        }
        let Some(dir) = self.view_root else {
            return;
        };
        let indices: Vec<TreeIndex> = self.entries.iter().map(|e| e.index).collect();
        let paths: Vec<PathBuf> = indices.iter().map(|&i| self.path_of(i)).collect();
        let name = self
            .selected
            .and_then(|s| self.traversal.tree.get(s))
            .map(|d| d.name.clone());
        self.remove_nodes(&indices);
        self.reselect_name = name;
        self.selected = None;
        self.start_refresh(paths, dir);
    }

    /// Remove nodes from the tree, fixing up marks, bookmarks and the view.
    fn remove_nodes(&mut self, indices: &[TreeIndex]) {
        let mut removed_all: Vec<TreeIndex> = Vec::new();
        for &idx in indices {
            removed_all.extend(self.traversal.tree.remove_subtree(idx));
        }
        let removed: HashSet<TreeIndex> = removed_all.into_iter().collect();
        if !removed.is_empty() {
            self.marked.retain(|i| !removed.contains(i));
            self.marked_set.retain(|i| !removed.contains(i));
            if let Some(pane) = self.mark_pane.as_mut() {
                pane.errors.retain(|i, _| !removed.contains(i));
                if let Some(sel) = pane.selected {
                    if self.marked.is_empty() {
                        pane.selected = None;
                    } else {
                        pane.selected = Some(sel.min(self.marked.len() - 1));
                    }
                }
            }
            if self.marked.is_empty() {
                self.mark_pane = None;
                if self.focus == Focus::Mark {
                    self.focus = Focus::Main;
                }
            }
            self.bookmarks
                .retain(|k, v| !removed.contains(k) && !removed.contains(v));
            if let Some(g) = self.glob.as_mut() {
                g.results.retain(|i| !removed.contains(i));
                if removed.contains(&g.search_root) {
                    g.search_root = self.traversal.root_index;
                }
                if let Some(prev) = g.previous_selection {
                    if removed.contains(&prev) {
                        g.previous_selection = None;
                    }
                }
            }
            if let Some(dir) = self.view_root {
                if removed.contains(&dir) {
                    // Go up to the closest existing ancestor.
                    let mut cur = dir;
                    let mut found = self.traversal.root_index;
                    while let Some(p) = self.traversal.tree.parent(cur) {
                        if self.traversal.tree.contains(p) {
                            found = p;
                            break;
                        }
                        cur = p;
                    }
                    self.view_root = Some(found);
                }
            }
            if let Some(sel) = self.selected {
                if removed.contains(&sel) {
                    self.selected = None;
                }
            }
        }
    }

    // ----- deletion -------------------------------------------------------------------------

    pub fn deletion_in_progress(&self) -> bool {
        self.deletion.is_some()
    }

    fn start_deletion(&mut self, to_trash: bool) {
        if self.marked.is_empty() {
            return;
        }
        self.deletion = Some(DeletionState {
            queue: self.marked.clone(),
            deleted_items: 0,
            to_trash,
        });
        self.message = Some("Deleted 0 items...".to_string());
    }

    /// Delete the next marked entry.
    pub fn deletion_step(&mut self) {
        let Some(state) = self.deletion.as_mut() else {
            return;
        };
        if state.queue.is_empty() {
            self.finish_deletion();
            return;
        }
        let idx = state.queue.remove(0);
        let to_trash = state.to_trash;
        if !self.traversal.tree.contains(idx) || !self.marked_set.contains(&idx) {
            return;
        }
        let path = self.path_of(idx);
        let count = self
            .traversal
            .tree
            .get(idx)
            .map(|d| count_of(d.entry_count))
            .unwrap_or(1);
        let errors = if to_trash {
            match trash::move_to_trash(&path) {
                Ok(()) => 0,
                Err(_) => 1,
            }
        } else {
            delete_recursively(&path)
        };
        if errors == 0 {
            let selected_pos = self.selected_position();
            let parent = self.traversal.tree.parent(idx);
            self.remove_nodes(&[idx]);
            if let Some(p) = parent {
                if self.traversal.tree.contains(p) {
                    self.traversal.recompute_ancestors(p);
                }
            }
            self.recompute_entries();
            if self.selected.is_none() {
                if let Some(pos) = selected_pos {
                    self.select_position(pos);
                }
            }
            if let Some(state) = self.deletion.as_mut() {
                state.deleted_items += count;
                self.message = Some(format!("Deleted {} items...", state.deleted_items));
            }
        } else if let Some(pane) = self.mark_pane.as_mut() {
            *pane.errors.entry(idx).or_insert(0) += errors;
        }
        if self
            .deletion
            .as_ref()
            .map(|s| s.queue.is_empty())
            .unwrap_or(true)
        {
            self.finish_deletion();
        }
    }

    fn finish_deletion(&mut self) {
        self.deletion = None;
        self.message = None;
        if self.marked.is_empty() {
            self.mark_pane = None;
            if self.focus == Focus::Mark {
                self.focus = Focus::Main;
            }
        }
        self.recompute_entries();
    }
}

/// Recursively delete a path, returning the number of errors encountered.
fn delete_recursively(path: &Path) -> u64 {
    let meta = match fs::symlink_metadata(path) {
        Ok(m) => m,
        Err(_) => return 1,
    };
    if meta.is_dir() {
        let mut errors = 0;
        match fs::read_dir(path) {
            Ok(iter) => {
                for entry in iter {
                    match entry {
                        Ok(entry) => errors += delete_recursively(&entry.path()),
                        Err(_) => errors += 1,
                    }
                }
            }
            Err(_) => errors += 1,
        }
        if fs::remove_dir(path).is_err() {
            errors += 1;
        }
        errors
    } else if fs::remove_file(path).is_err() {
        1
    } else {
        0
    }
}

pub fn sort_entries(items: &mut [EntryItem], mode: SortMode) {
    match mode {
        SortMode::SizeDescending => items.sort_by(|a, b| b.size.cmp(&a.size)),
        SortMode::SizeAscending => items.sort_by(|a, b| a.size.cmp(&b.size)),
        SortMode::MTimeDescending => items.sort_by(|a, b| b.mtime.cmp(&a.mtime)),
        SortMode::MTimeAscending => items.sort_by(|a, b| a.mtime.cmp(&b.mtime)),
        SortMode::CountDescending => items.sort_by(|a, b| {
            (b.entry_count, b.name.as_bytes()).cmp(&(a.entry_count, a.name.as_bytes()))
        }),
        SortMode::CountAscending => items.sort_by(|a, b| {
            (a.entry_count, a.name.as_bytes()).cmp(&(b.entry_count, b.name.as_bytes()))
        }),
        SortMode::NameAscending => items.sort_by(|a, b| {
            (!a.is_dir, a.name.as_bytes()).cmp(&(!b.is_dir, b.name.as_bytes()))
        }),
        SortMode::NameDescending => items.sort_by(|a, b| {
            (!b.is_dir, b.name.as_bytes()).cmp(&(!a.is_dir, a.name.as_bytes()))
        }),
    }
}

