}

fn absolute(path: &Path) -> PathBuf {
    if path.is_absolute() {
        path.to_path_buf()
    } else {
        env::current_dir()
            .map(|cwd| cwd.join(path))
            .unwrap_or_else(|_| path.to_path_buf())
    }
}

fn percent_encode(path: &Path) -> String {
    let mut out = String::new();
    for &b in path.as_os_str().as_encoded_bytes() {
        let keep = b.is_ascii_alphanumeric() || matches!(b, b'/' | b'-' | b'_' | b'.' | b'~');
        if keep {
            out.push(b as char);
        } else {
            out.push_str(&format!("%{:02X}", b));
        }
    }
    out
}

/// Find the mount point containing `path` by walking up until the device changes.
fn mount_point_of(path: &Path, dev: u64) -> PathBuf {
    let mut current = path.to_path_buf();
    loop {
        let parent = match current.parent() {
            Some(p) => p.to_path_buf(),
            None => return current,
        };
        match fs::metadata(&parent) {
            Ok(m) if m.dev() == dev => current = parent,
            _ => return current,
        }
    }
}

fn ensure_trash_dirs(trash: &Path) -> io::Result<(PathBuf, PathBuf)> {
    let files = trash.join("files");
    let info = trash.join("info");
    for dir in [trash, &files, &info] {
        if !dir.is_dir() {
            fs::create_dir_all(dir)?;
            fs::set_permissions(dir, fs::Permissions::from_mode(0o700))?;
        }
    }
    Ok((files, info))
}

pub fn move_to_trash(path: &Path) -> io::Result<()> {
    let abs = absolute(path);
    let meta = fs::symlink_metadata(&abs)?;
    let parent = abs
        .parent()
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "cannot trash root"))?;
    let parent_dev = fs::metadata(parent)?.dev();
    let _ = meta;

    let home_trash = home_trash_dir()
        .ok_or_else(|| io::Error::new(io::ErrorKind::NotFound, "no home directory"))?;
    let home_dev = home_trash
        .ancestors()
        .find_map(|a| fs::metadata(a).ok().map(|m| m.dev()));

    let trash_dir = if home_dev == Some(parent_dev) {
        home_trash
    } else {
        let uid = unsafe { libc::getuid() };
        let mount = mount_point_of(parent, parent_dev);
        let top = mount.join(".Trash");
        match fs::symlink_metadata(&top) {
            Ok(m) if m.is_dir() && (m.mode() & 0o1000) != 0 => top.join(uid.to_string()),
            _ => mount.join(format!(".Trash-{}", uid)),
        }
    };
    let (files_dir, info_dir) = ensure_trash_dirs(&trash_dir)?;

    let file_name = abs
        .file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "no file name"))?;
    let mut appendage = 1u64;
    let (info_path, in_trash_name) = loop {
        let name = if appendage > 1 {
            format!("{}.{}", file_name, appendage)
        } else {
            file_name.clone()
        };
        let info_path = info_dir.join(format!("{}.trashinfo", name));
        match OpenOptions::new()
            .create_new(true)
            .write(true)
            .open(&info_path)
        {
            Ok(mut f) => {
                let now = chrono::Local::now();
                let content = format!(
                    "[Trash Info]\nPath={}\nDeletionDate={}\n",
                    percent_encode(&abs),
                    now.format("%Y-%m-%dT%H:%M:%S")
                );
                f.write_all(content.as_bytes())?;
                break (info_path, name);
            }
            Err(e) if e.kind() == io::ErrorKind::AlreadyExists => {
                appendage += 1;
                continue;
            }
            Err(e) => return Err(e),
        }
    };
    let target = files_dir.join(&in_trash_name);
    if let Err(e) = fs::rename(&abs, &target) {
        fs::remove_file(&info_path).ok();
        return Err(e);
    }
    Ok(())
}
