fn render_help(app: &mut App, buf: &mut Buffer, area: Rect, focused: bool) {
    let style = border_style(focused);
    let right_title = if focused { Some(NAV_HINT) } else { None };
    let inner = draw_block(buf, area, style, "Help", right_title, None);
    if inner.width == 0 || inner.height == 0 {
        return;
    }
    app.last_help_height = inner.height as usize;
    let lines = help_lines();
    let max_scroll = lines.len().saturating_sub(inner.height as usize);
    let scroll = app
        .help_pane
        .as_ref()
        .map(|p| p.scroll.min(max_scroll))
        .unwrap_or(0);
    if let Some(p) = app.help_pane.as_mut() {
        p.scroll = scroll;
    }
    let max_x = inner.right();
    // The first row stays empty.
    let mut y = inner.y + 1;
    for line in lines.iter().skip(scroll) {
        if y >= inner.bottom() {
            break;
        }
        let x = inner.x;
        match line {
            HelpLine::Blank => {}
            HelpLine::Title(t) => {
                let nx = put_str(buf, x, y, max_x, " ", Style::default());
                put_padded(
                    buf,
                    nx,
                    y,
                    max_x,
                    t,
                    Style::default().add_modifier(Modifier::BOLD | Modifier::UNDERLINED),
                );
            }
            HelpLine::Key(key, desc) => {
                let nx = put_str(buf, x, y, max_x, " ", Style::default());
                let text = format!("{:>12} => {}", key, desc);
                put_padded(buf, nx, y, max_x, &text, Style::default().fg(Color::Green));
            }
            HelpLine::Continuation(text) => {
                let nx = put_str(buf, x, y, max_x, " ", Style::default());
                let text = format!("{:>12}    {}", "", text);
                put_str(buf, nx, y, max_x, &text, Style::default());
            }
        }
        y += 1;
    }
}

// ----- mark pane ----------------------------------------------------------------------------

fn mark_size_cell(byte_format: ByteFormat, size: u128) -> String {
    let mut s = format!("{:>w$}", byte_format.display(size).to_string(), w = byte_format.width());
    for _ in 1..byte_format.unit_width() {
        s.push(' ');
    }
    s
}

fn render_mark(app: &mut App, buf: &mut Buffer, area: Rect, focused: bool) {
    let style = border_style(focused);
    let (count, size) = app.marked_total();
    let title = format!("Marked {} items ({}) ", count, app.byte_format.display(size));
    let bottom_title = if focused {
        Some(" mark-toggle = space,d | remove-all = a")
    } else {
        None
    };
    let inner = draw_block(buf, area, style, &title, None, bottom_title);
    if inner.width == 0 || inner.height == 0 {
        return;
    }
    let selected = app.mark_pane.as_ref().and_then(|p| p.selected);
    let len = app.marked.len();
    let height = inner.height as usize;
    let show_hint = selected.is_some() && height > 1;
    let list_height = if show_hint { height - 1 } else { height };
    let mut offset = app.mark_pane.as_ref().map(|p| p.list_offset).unwrap_or(0);
    if let Some(sel) = selected {
        if sel < offset {
            offset = sel;
        } else if sel >= offset + list_height {
            offset = sel + 1 - list_height;
        }
    }
    if offset + list_height > len {
        offset = len.saturating_sub(list_height);
    }
    if let Some(p) = app.mark_pane.as_mut() {
        p.list_offset = offset;
    }
    app.last_mark_list_height = list_height;

    let hint_at_top = match selected {
        Some(sel) if show_hint => sel.saturating_sub(offset) < list_height / 2,
        _ => true,
    };
    let list_y = if show_hint && hint_at_top {
        inner.y + 1
    } else {
        inner.y
    };
    if show_hint {
        let hint_y = if hint_at_top {
            inner.y
        } else {
            inner.y + list_height as u16
        };
        let max_x = inner.right();
        let mut x = inner.x;
        x = put_str(
            buf,
            x,
            hint_y,
            max_x,
            " Ctrl + t ",
            Style::default().fg(Color::White).bg(Color::Black).add_modifier(Modifier::BOLD),
        );
        let yellow = Style::default().fg(Color::Black).bg(Color::Yellow).add_modifier(Modifier::BOLD);
        x = put_str(buf, x, hint_y, max_x, " to trash or ", yellow);
        x = put_str(
            buf,
            x,
            hint_y,
            max_x,
            " Ctrl + r ",
            Style::default()
                .fg(Color::LightRed)
                .bg(Color::Black)
                .add_modifier(Modifier::BOLD | Modifier::RAPID_BLINK),
        );
        put_padded(buf, x, hint_y, max_x, " to delete without prompt", yellow);
    }

    let byte_format = app.byte_format;
    let errors = app.mark_pane.as_ref().map(|p| p.errors.clone()).unwrap_or_default();
    for (row, &idx) in app.marked.iter().skip(offset).take(list_height).enumerate() {
        let y = list_y + row as u16;
        let Some(data) = app.traversal.tree.get(idx) else { continue };
        let is_selected = selected == Some(offset + row);
        let base = if is_selected {
            Style::default().add_modifier(Modifier::BOLD | Modifier::REVERSED)
        } else {
            Style::default()
        };
        let name_color = if data.is_dir_display_for_mark(&app.traversal.tree, idx) {
            Color::Yellow
        } else {
            Color::Rgb(176, 126, 0)
        };
        let path = app.path_of(idx).display().to_string();
        let name = match errors.get(&idx) {
            Some(n) => format!(" {}  {} IO deletion errors", path, n),
            None => format!(" {}", path),
        };
        let size_cell = mark_size_cell(byte_format, data.size);
        let size_w = size_cell.width() as u16;
        let max_x = inner.right();
        let name_max = max_x.saturating_sub(size_w).max(inner.x);
        put_padded(buf, inner.x, y, name_max, &name, base.fg(name_color));
        put_str(buf, name_max, y, max_x, &size_cell, base.fg(Color::Green));
    }
    if len > 0 {
        draw_scrollbar(buf, inner, area.right() - 1, len, selected.unwrap_or(0), style);
    }
}

// ----- glob pane ----------------------------------------------------------------------------

fn render_glob(app: &App, buf: &mut Buffer, area: Rect, focused: bool) {
    let style = border_style(focused);
    let (title, input) = match app.glob.as_ref() {
        Some(g) => (
            format!(
                "Git-Glob ({})",
                if g.case_insensitive {
                    "case-insensitive"
                } else {
                    "case-sensitive"
                }
            ),
            g.input.clone(),
        ),
        None => ("Git-Glob (case-insensitive)".to_string(), String::new()),
    };
    let right_title = if focused {
        Some(" search = enter | case = ^f | cancel = esc ")
    } else {
        None
    };
    let inner = draw_block(buf, area, style, &title, right_title, None);
    if inner.width == 0 || inner.height == 0 {
        return;
    }
    put_str(
        buf,
        inner.x,
        inner.y,
        inner.right(),
        &format!(" {}", input),
        Style::default(),
    );
}

trait MarkDisplay {
    fn is_dir_display_for_mark(&self, tree: &super::tree::Tree, idx: super::tree::TreeIndex) -> bool;
}

impl MarkDisplay for super::tree::EntryData {
    fn is_dir_display_for_mark(&self, tree: &super::tree::Tree, idx: super::tree::TreeIndex) -> bool {
        // Directories are shown in a brighter yellow in the mark pane.
        let _ = count_of;
        tree.has_children(idx) || self.is_dir
    }
}
