//! Rendering of all panes.
use ratatui::buffer::Buffer;
use ratatui::layout::{Constraint, Layout, Rect};
use ratatui::style::{Color, Modifier, Style};
use ratatui::Frame;
use unicode_segmentation::UnicodeSegmentation;
use unicode_width::UnicodeWidthStr;

use super::app::{count_of, App, DisplayMode, Focus};
use crate::byte_format::ByteFormat;

pub const VERSION: &str = "2.32.2";

// ----- low level drawing helpers -------------------------------------------------------------

/// Write `text` starting at (x, y), never exceeding `max_x` (exclusive). Returns the next x.
fn put_str(buf: &mut Buffer, mut x: u16, y: u16, max_x: u16, text: &str, style: Style) -> u16 {
    if y >= buf.area.bottom() {
        return x;
    }
    for g in text.graphemes(true) {
        let w = g.width() as u16;
        if w == 0 {
            continue;
        }
        if x + w > max_x {
            break;
        }
        if let Some(cell) = buf.cell_mut((x, y)) {
            cell.set_symbol(g);
            cell.set_style(style);
        }
        for i in 1..w {
            if let Some(cell) = buf.cell_mut((x + i, y)) {
                cell.set_symbol("");
                cell.set_style(style);
            }
        }
        x += w;
    }
    x
}

/// Fill from x to max_x with spaces in the given style.
fn fill(buf: &mut Buffer, x: u16, y: u16, max_x: u16, style: Style) {
    if y >= buf.area.bottom() {
        return;
    }
    for cx in x..max_x {
        if let Some(cell) = buf.cell_mut((cx, y)) {
            cell.set_symbol(" ");
            cell.set_style(style);
        }
    }
}

/// Write text and pad with spaces to max_x.
fn put_padded(buf: &mut Buffer, x: u16, y: u16, max_x: u16, text: &str, style: Style) -> u16 {
    let nx = put_str(buf, x, y, max_x, text, style);
    fill(buf, nx, y, max_x, style);
    max_x
}

/// Draw a block with borders and optional titles. Returns the inner area.
fn draw_block(
    buf: &mut Buffer,
    area: Rect,
    style: Style,
    title_left: &str,
    title_right: Option<&str>,
    title_bottom_right: Option<&str>,
) -> Rect {
    if area.width < 2 || area.height < 2 {
        return Rect::new(area.x, area.y, 0, 0);
    }
    let right = area.right() - 1;
    let bottom = area.bottom() - 1;
    for y in area.top()..area.bottom() {
        for x in area.left()..area.right() {
            let symbol = match (x == area.left(), x == right, y == area.top(), y == bottom) {
                (true, _, true, _) => "┌",
                (_, true, true, _) => "┐",
                (true, _, _, true) => "└",
                (_, true, _, true) => "┘",
                (true, _, _, _) | (_, true, _, _) => "│",
                (_, _, true, _) | (_, _, _, true) => "─",
                _ => continue,
            };
            if let Some(cell) = buf.cell_mut((x, y)) {
                cell.set_symbol(symbol);
                cell.set_style(style);
            }
        }
    }
    let title_max_x = right;
    put_str(buf, area.left() + 1, area.top(), title_max_x, title_left, style);
    if let Some(t) = title_right {
        let w = t.width() as u16;
        let start = right.saturating_sub(w).max(area.left() + 1);
        put_str(buf, start, area.top(), title_max_x, t, style);
    }
    if let Some(t) = title_bottom_right {
        let w = t.width() as u16;
        let start = right.saturating_sub(w).max(area.left() + 1);
        put_str(buf, start, bottom, title_max_x, t, style);
    }
    Rect::new(
        area.x + 1,
        area.y + 1,
        area.width.saturating_sub(2),
        area.height.saturating_sub(2),
    )
}

/// Draws a scrollbar over the right border of `block_area` for the given inner area.
fn draw_scrollbar(buf: &mut Buffer, inner: Rect, block_right_x: u16, content_len: usize, position: usize, style: Style) {
    let track_len = inner.height as usize;
    if track_len == 0 || content_len == 0 {
        return;
    }
    let track = track_len as f64;
    let viewport = track;
    let max_position = content_len.saturating_sub(1) as f64;
    let start_position = (position as f64).clamp(0.0, max_position);
    let max_viewport_position = max_position + viewport;
    let thumb_start = (start_position * track / max_viewport_position).round() as usize;
    let thumb_end = ((start_position + viewport) * track / max_viewport_position).round() as usize;
    let thumb_len = thumb_end.saturating_sub(thumb_start).max(1);
    for i in 0..track_len {
        let symbol = if i >= thumb_start && i < thumb_start + thumb_len {
            "█"
        } else {
            "║"
        };
        if let Some(cell) = buf.cell_mut((block_right_x, inner.y + i as u16)) {
            cell.set_symbol(symbol);
            cell.set_style(style);
        }
    }
}

fn border_style(focused: bool) -> Style {
    if focused {
        Style::default().add_modifier(Modifier::BOLD)
    } else {
        Style::default().fg(Color::DarkGray)
    }
}

const NAV_HINT: &str = " . = o|.. = u ── ⇊ = Ctrl+d|↓ = j|⇈ = Ctrl+u|↑ = k ";

pub fn count_format(count: u64) -> String {
    if count >= 1_000_000_000_000 {
        format!("{}T", count / 1_000_000_000_000)
    } else if count >= 1_000_000_000 {
        format!("{}G", count / 1_000_000_000)
    } else if count >= 1_000_000 {
        format!("{}M", count / 1_000_000)
    } else if count >= 1_000 {
        format!("{}K", count / 1_000)
    } else {
        count.to_string()
    }
}

// ----- main entry point ---------------------------------------------------------------------

pub fn render(app: &mut App, frame: &mut Frame) {
    let area = frame.area();
    let buf = frame.buffer_mut();
    if area.height == 0 || area.width == 0 {
        return;
    }
    let header = Rect::new(area.x, area.y, area.width, 1);
    let footer_y = area.bottom() - 1;
    let footer = Rect::new(area.x, footer_y, area.width, 1);
    let middle = Rect::new(
        area.x,
        area.y + 1,
        area.width,
        area.height.saturating_sub(2),
    );

    render_header(app, buf, header);
    render_footer(app, buf, footer);

    let has_right = app.help_pane.is_some() || app.mark_pane.is_some();
    let (left, right) = if has_right && middle.width > 0 {
        let chunks = Layout::horizontal([Constraint::Percentage(50), Constraint::Percentage(50)])
            .split(middle);
        (chunks[0], Some(chunks[1]))
    } else {
        (middle, None)
    };
    let glob_open = app.glob.as_ref().map(|g| g.pane_open).unwrap_or(false);
    let (main_area, glob_area) = if glob_open {
        let chunks = Layout::vertical([Constraint::Min(0), Constraint::Length(3)]).split(left);
        (chunks[0], Some(chunks[1]))
    } else {
        (left, None)
    };
    render_entries(app, buf, main_area, app.focus == Focus::Main);
    if let Some(ga) = glob_area {
        render_glob(app, buf, ga, app.focus == Focus::Glob);
    }
    if let Some(right) = right {
        match (app.help_pane.is_some(), app.mark_pane.is_some()) {
            (true, true) => {
                let chunks =
                    Layout::vertical([Constraint::Percentage(50), Constraint::Percentage(50)])
                        .split(right);
                render_help(app, buf, chunks[0], app.focus == Focus::Help);
                render_mark(app, buf, chunks[1], app.focus == Focus::Mark);
            }
            (true, false) => render_help(app, buf, right, app.focus == Focus::Help),
            (false, true) => render_mark(app, buf, right, app.focus == Focus::Mark),
            (false, false) => {}
        }
    }
}

// ----- header -------------------------------------------------------------------------------

fn render_header(app: &App, buf: &mut Buffer, area: Rect) {
    let bg = if app.focus == Focus::Mark && app.mark_pane.is_some() {
        Color::LightRed
    } else if !app.marked.is_empty() {
        Color::Yellow
    } else {
        Color::White
    };
    let base = Style::default().fg(Color::Black).bg(bg);
    let bold = base.add_modifier(Modifier::BOLD);
    let underlined = base.add_modifier(Modifier::UNDERLINED);
    let bold_underlined = underlined.add_modifier(Modifier::BOLD);
    let y = area.y;
    let max_x = area.right();
    let mut x = area.x;
    x = put_str(buf, x, y, max_x, " D", bold);
    x = put_str(buf, x, y, max_x, "isk ", base);
    x = put_str(buf, x, y, max_x, "U", bold);
    x = put_str(buf, x, y, max_x, "sage ", base);
    x = put_str(buf, x, y, max_x, "A", bold);
    x = put_str(buf, x, y, max_x, &format!("nalyzer v{}    ", VERSION), base);
    x = put_str(buf, x, y, max_x, "(press ", underlined);
    x = put_str(buf, x, y, max_x, "?", bold_underlined);
    x = put_str(buf, x, y, max_x, " for help)", underlined);
    fill(buf, x, y, max_x, base);
}

// ----- footer -------------------------------------------------------------------------------

fn format_elapsed(app: &App) -> String {
    let n = app.traversal.entries_traversed;
    match app.traversal.elapsed {
        Some(elapsed) if !app.is_scanning() => format!("{:.2}s", elapsed.as_secs_f64()),
        _ => {
            let elapsed = app.traversal.start.elapsed();
            let secs = elapsed.as_secs_f64();
            let rate = if secs > 0.0 {
                (n as f64 / secs) as u64
            } else {
                0
            };
            format!("{}s ({}/s)", elapsed.as_secs(), rate)
        }
    }
}

fn render_footer(app: &App, buf: &mut Buffer, area: Rect) {
    let y = area.y;
    let max_x = area.right();
    if app.quit_pending {
        let style = Style::default()
            .fg(Color::Black)
            .bg(Color::Yellow)
            .add_modifier(Modifier::BOLD);
        put_padded(buf, area.x, y, max_x, "Press esc or q again to exit...", style);
        return;
    }
    let reversed = Style::default().add_modifier(Modifier::REVERSED);
    let total = app
        .traversal
        .total_bytes
        .unwrap_or_else(|| app.traversal.tree.get(app.traversal.root_index).map(|d| d.size).unwrap_or(0));
    let text = format!(
        "Sort mode: {}  Total disk usage: {}  Processed {} entries in {}",
        app.sorting.label(),
        app.byte_format.display(total),
        app.traversal.entries_traversed,
        format_elapsed(app)
    );
    let mut x = put_str(buf, area.x, y, max_x, &text, reversed);
    if let Some(msg) = app.message.as_ref() {
        x = put_str(buf, x, y, max_x, "  ", reversed);
        let msg_style = Style::default()
            .fg(Color::Red)
            .add_modifier(Modifier::BOLD | Modifier::RAPID_BLINK | Modifier::REVERSED);
        x = put_str(buf, x, y, max_x, msg, msg_style);
    }
    fill(buf, x, y, max_x, reversed);
}

// ----- entries pane -------------------------------------------------------------------------

const PARTIAL_BLOCKS: [&str; 8] = ["", "▏", "▎", "▍", "▌", "▋", "▊", "▉"];

pub fn bar(fraction: f64, width: usize) -> String {
    let scaled = fraction.max(0.0) * width as f64;
    let mut full = scaled.floor() as usize;
    let remainder = scaled - full as f64;
    let mut eighths = (remainder * 8.0).round() as usize;
    if eighths >= 8 {
        full += 1;
        eighths = 0;
    }
    full = full.min(width);
    let mut s = String::new();
    for _ in 0..full {
        s.push('█');
    }
    let mut used = full;
    if eighths > 0 && used < width {
        s.push_str(PARTIAL_BLOCKS[eighths]);
        used += 1;
    }
    for _ in used..width {
        s.push(' ');
    }
    s
}

fn percentage_cell(mode: DisplayMode, fraction: f64) -> String {
    let pct = format!(" {:>5.1}% ", fraction * 100.0);
    match mode {
        DisplayMode::PercentageAndBar => format!("{} {}", pct, bar(fraction, 10)),
        DisplayMode::Percentage => pct,
        DisplayMode::Bar => bar(fraction, 10),
        DisplayMode::LongBar => bar(fraction, 19),
    }
}

fn mtime_text(mtime: std::time::SystemTime) -> String {
    let dt: chrono::DateTime<chrono::Local> = mtime.into();
    format!(" {}", dt.format("%d/%m/%Y %H:%M:%S"))
}

fn render_entries(app: &mut App, buf: &mut Buffer, area: Rect, focused: bool) {
    let style = border_style(focused);
    let total_size = app.entries_total_size();
    let total_count = app.entries_total_count();
    let title = format!(
        " {} ({} visible, {} total, {}) ",
        app.view_title_path(),
        app.entries.len(),
        count_format(total_count),
        app.byte_format.display(total_size)
    );
    let (right_title, bottom_title) = if focused {
        (
            Some(NAV_HINT),
            Some(" mark-move = d | mark-toggle = space | toggle-all = a "),
        )
    } else {
        (None, None)
    };
    let inner = draw_block(buf, area, style, &title, right_title, bottom_title);
    if inner.width == 0 || inner.height == 0 {
        return;
    }
    let height = inner.height as usize;

    // Scrolling: keep the selected entry visible.
    let selected_pos = app.selected_position();
    let mut offset = app.list_offset;
    if let Some(sel) = selected_pos {
        if sel < offset {
            offset = sel;
        } else if sel >= offset + height {
            offset = sel + 1 - height;
        }
    }
    if offset + height > app.entries.len() {
        offset = app.entries.len().saturating_sub(height);
    }
    if selected_pos.is_none() {
        offset = 0;
    }
    app.list_offset = offset;

    let show_mtime = app.show_mtime || app.sorting.is_mtime();
    let show_count = app.show_count || app.sorting.is_count();
    let byte_format = app.byte_format;
    let size_width = byte_format.width();
    let sorting = app.sorting;
    let display_mode = app.display_mode;
    let is_scanning = app.is_scanning();

    for (row, item) in app.entries.iter().skip(offset).take(height).enumerate() {
        let y = inner.y + row as u16;
        let is_selected = Some(item.index) == app.selected;
        let fraction = if total_size > 0 {
            item.size as f64 / total_size as f64
        } else {
            0.0
        };
        let base = if is_selected && focused {
            Style::default().add_modifier(Modifier::BOLD)
        } else {
            Style::default()
        };
        let cell_style = if is_selected {
            base.add_modifier(Modifier::REVERSED)
        } else {
            base
        };
        let column_style = if is_selected && fraction <= 0.9 {
            base.add_modifier(Modifier::REVERSED)
        } else {
            base
        };
        let green = Color::Green;
        let mut x = inner.x;
        let max_x = inner.right();
        if show_mtime {
            let s = if sorting.is_mtime() {
                cell_style.fg(green)
            } else {
                cell_style
            };
            x = put_str(buf, x, y, max_x, &mtime_text(item.mtime), s);
            x = put_str(buf, x, y, max_x, " | ", column_style);
        }
        let size_style = if sorting.is_size() {
            cell_style.fg(green)
        } else {
            cell_style
        };
        x = put_str(buf, x, y, max_x, &format!("{:>w$}", byte_format.display(item.size).to_string(), w = size_width), size_style);
        x = put_str(buf, x, y, max_x, " | ", column_style);
        x = put_str(buf, x, y, max_x, &percentage_cell(display_mode, fraction), column_style);
        x = put_str(buf, x, y, max_x, " | ", column_style);
        if show_count {
            let s = if sorting.is_count() {
                cell_style.fg(green)
            } else {
                cell_style
            };
            let text = match item.entry_count {
                Some(c) => format!("{:>4}", c),
                None => "    ".to_string(),
            };
            x = put_str(buf, x, y, max_x, &text, s);
            x = put_str(buf, x, y, max_x, " | ", column_style);
        }
        let is_marked = app.is_marked(item.index);
        let name_style = if item.metadata_io_error || !item.exists {
            cell_style.fg(Color::Red)
        } else if is_marked {
            if item.is_dir {
                cell_style.fg(Color::Yellow)
            } else {
                cell_style.fg(Color::Rgb(176, 126, 0))
            }
        } else if item.is_dir {
            cell_style.fg(Color::Cyan)
        } else {
            cell_style
        };
        let name = format!("{}{}", if item.is_dir { "/" } else { " " }, item.name);
        put_padded(buf, x, y, max_x, &name, name_style);
        let _ = is_scanning;
    }
    if !app.entries.is_empty() {
        let position = selected_pos.unwrap_or(0);
        draw_scrollbar(buf, inner, area.right() - 1, app.entries.len(), position, style);
    }
}

// ----- help pane ----------------------------------------------------------------------------

pub enum HelpLine {
